quests[31930] = { id = 31930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Pandaria", description = "Jetzt müsst Ihr den zähesten Zähmern in ganz Azeroth gegenübertreten, {name}. Sie haben sich in Pandaria niedergelassen, der Heimat der Großmeister.\n\nSechs Großmeister gibt es noch zu besiegen: Hyuna von den Schreinen im Jadewald, Bäuerin Nishi im Tal der Vier Winde, Mo'ruk in der Krasarangwildnis, den mutigen Yon am Kun-Lai-Gipfel, Sucher Zusshi in der Tonlongsteppe und Ödniswandler Shu in der Schreckensöde.\n\nWenn Ihr glaubt, dass Ihr bereit seid, stellt Euch diesen Meistern ihres Fachs und beweist Euer Können!", sourceObjective = "Besiegt Hyuna von den Schreinen, Bäuerin Nishi, Mo'ruk, Yon den Mutigen, Sucher Zusshi und Ödniswandler Shu in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31931] = { id = 31931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beegli Lunte", description = "Eins von meinen Hühnern ist gestern ganz kurz geflogen. Ich schwör's. Endlich kommen wir ganz groß raus!\n\nAch, Ihr wollt schon wieder kämpfen?", sourceObjective = "Besiegt Beegli Lunte in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31932] = { id = 31932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fast kopfloser Jakob", description = "Ihr widersetzt Euch meiner Weisheit immer wieder. Was führt Euch in diese Wälder zurück?\n\nAch, Ihr wollt noch einmal kämpfen. Also gut.", sourceObjective = "Besiegt den fast kopflosen Jakob in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31933] = { id = 31933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrut Drachenwüste", description = "Ihr wagt es, unsere Arbeit zu unterbrechen? Dann müsst Ihr erneut gegen mich kämpfen! Holt Eure Haustiere heraus, dann werde ich Euch Höllschreis Zorn schmecken lassen!", sourceObjective = "Besiegt Okrut Drachenwüste in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31934] = { id = 31934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darmwürger", description = "Ich Euch gerne bekämpfen. Ihr nicht so einfach wie andere. Wir nochmal kämpfen?", sourceObjective = "Besiegt Darmwürger in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31935] = { id = 31935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Payne", description = "<Dieser/Diese:c> rebellische {class} ist also wieder da, um <seine/ihre> Kräfte mit denen des Großmeisters zu messen. Dieses Mal wird Eure Kühnheit Euer Verderben sein!", sourceObjective = "Besiegt Major Payne in einem Haustierkampf.", completion = "Ich applaudiere Eurer Taktik, doch ich verachte Euren Sieg. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31936] = { id = 31936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bewässerungssystem \"Jinyuprinzessin\"", description = "<Auf der Rückseite der Kiste ist die Karikatur einer Jinyuprinzessin abgebildet, die vom folgenden Werbetext umrahmt wird:>\n\n\"Hallo, grüner Daumen! Knatschig über krass vertrocknete Kürbisse? Klagen über krustigen Kohl? Ist Euer Lauch lahm und sind Eure Melonen melancholisch?\n\nDann ist die Zeit gekommen, die Jinyuprinzessin nach Hause zu bringen! Sie wird Euren Garten wie feiner Frühlingsregen bewässern und die Dürre mit einem soliden Schluck...\"\n\n<Und so geht es sechs Absätze lang weiter.>", sourceObjective = "Bringt das Bewässerungssystem \"Jinyuprinzessin\" zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand:", completion = "Ein Bewässerungssystem? Für den Hof? Danke, {name}! Wir können es anstatt der alten Gießkanne verwenden.\n\nDie \"Jinyuprinzessin\"? Was hat es damit auf sich?\n\n\n\nNa gut, ich will es gar nicht wissen. Ich werde es sofort aufstellen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31937] = { id = 31937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezieferschutz \"Donnerkönig\"", description = "<Das Ehrfurcht gebietende Konterfei eines Mogu prangt auf dieser Kiste; sein Blick ist auf die fein säuberlich darunter angeordneten fett gedruckten Zeilen gerichtet.>\n\n\"LASST EUCH EURE ERNTE NICHT DURCH SCHWACHE, EKEL ERREGENDE INSEKTEN VERDERBEN. WERDET IHRER DANK DER MACHT DES DONNERKÖNIGS HERR UND SCHÜTZT EUER ERBE.\"\n\n<Die übrige Fläche ist mit Karikaturen wehklagender oder verschreckt fliehender Insekten bedeckt.>", sourceObjective = "Bringt den Ungezieferschutz \"Donnerkönig\" zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand:", completion = "Schädlingsbekämpfungsmittel! Ihr seid genial, {name}! Endlich müssen wir uns nicht mehr mit diesem altmodischen Insektenvernichtungsmittel abgeben.\n\n\n\nOh ja, der Donnerkönig! So habe ich mir das vorgestellt!\n\nIch werde mich sofort damit an die Arbeit machen - diese Viecher werden nicht wissen, wie ihnen geschieht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31938] = { id = 31938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der \"Erdschlitzer\"-Meisterpflug", description = "<Auf der Kiste ist ein Pandarenbauer mit einer unglaublichen Figur abgebildet, der voller Stolz mit gespreizten Beinen über einem breiter werdenden Riss im Boden steht und einen gewaltigen Pflug umklammert. Verspielte Junge tummeln sich auf seinen Schultern und baumeln von seinen muskulösen Armen.\n\nAn seiner Seite balanciert ein stoisches weibliches Wesen - mit ebenso unglaublicher Figur - ein gigantisches überschäumendes Füllhorn anmutig auf dem Kopf, während sie einem Shed-Ling einen Tritt ins Gesicht verpasst.>\n\n\"Der Erdschlitzer. Beherrscht das Land. Beherrscht Euer Leben.\"", sourceObjective = "Bringt den \"Erdschlitzer\"-Meisterpflug zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand:", completion = "Ein Erdschlitzer-Meisterpflug! Ich... ich hätte nie gedacht, dass ich jemals einen davon in die Hände bekommen würde. Ist Euch klar, wie viel Zeit wir damit sparen werden?!\n\nIch habe gehört, wenn Ihr mit dem Erdschlitzer zwanzig Meter solides Gestein durchpflügt, bekommt Ihr eine Sandkiste und eine Vorladung von den Shado-Pan für das Auslösen einer Erdbebenwarnung!\n\nDas wird der reine WAHNSINN.", sourceObjectiveStatus = "unverified-source-field" }
quests[31941] = { id = 31941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vierundsiebzig-elf: Kürbisch Wasser", description = "Großvater hat oft gesagt: \"Ein Kürbis pro Woche hilft, dass man nicht roche\".\n\n<Yoon schnüffelt fast unmerklich.>\n\nJawohl. Ich glaube, es ist ungefähr eine Woche her. Würdet Ihr mir helfen einen Jadekürbis zu pflanzen?", sourceObjective = "Pflanzt einen Jadekürbis auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Gut gepflanzt, {name}.\n\nUnd jetzt warten wir ab...", sourceObjectiveStatus = "unverified-source-field" }
quests[31942] = { id = 31942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melonensaison", description = "<Bauer Yoon schaut gen Himmel und schnuppert die Luft.>\n\nHmm...\n\n<Er leckt sich die Pfote und hält sie in die Brise, gräbt eine Zehe in den Boden und prüft dann die Länge seines Schattens.>\n\nJa. Die Melonensaison bricht an.\n\nKönntet Ihr mir ein paar Samen besorgen, damit ich Streifenmelonen anbauen kann?", sourceObjective = "Pflanzt eine Streifenmelone auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", progress = "Beeilt Euch! Die Melonensaison dauert nicht ewig!", completion = "Das war knapp. Fast hätten wir die Melonensaison verpasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31943] = { id = 31943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häh? Beeren? Hexenbeeren.", description = "Der Junge dort drüben, Andi, wird irgendwann zu einem tollen Bauern heranwachsen. Das sehe ich auf einen Blick.\n\nIch glaube, ich werde ein paar Hexenbeeren für ihn pflanzen. Kinder lieben Hexenbeeren. Das wird eine nette Überraschung.", sourceObjective = "Pflanzt Hexenbeeren auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", progress = "Das Geheimnis einer guten Hexenbeerenernte besteht darin zu warten, bis sie süß sind.\n\nDas ist nicht so einfach wie es klingt. Ich kann mich erinnern, wie ich als Kind bei Hexenbeeren, die noch nicht einmal halb reif waren, das Gesicht verzogen habe, weil ich zu ungeduldig war und einfach nicht auf meinen Opa hören wollte.", completion = "Hurra, Hexenbeeren! Ich kann es gar nicht erwarten!\n\nMuss ich aber.", sourceObjectiveStatus = "unverified-source-field" }
quests[31944] = { id = 31944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung abschließen: Die letzte Prüfung", description = "Willkommen zurück, {name}. Die Zeit ist gekommen, die letzte Phase Eurer Ausbildung zu absolvieren. Auf zum Ausbildungsgelände, damit Ihr Eure letzte Prüfung ablegen könnt.", sourceObjective = "Begebt Euch zum Ausbildungsgelände am Gipfel der Ruhe und legt Eure letzte Prüfung ab.", completion = "Gute Arbeit, {name}. Eure Ausbildung ist nun abgeschlossen. Kommt gerne auch in Zukunft wieder, um Eure Kräfte mit den Meistern hier zu messen und zu üben, was Ihr gelernt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31945] = { id = 31945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernen und Wachsen VI: Ginas Stimme", description = "Mein Geschäft ist dem Untergang geweiht! Seht Ihr all die Eisentatzen an ihren Kochstellen?\n\nIhre leckeren Gerichte locken viel Kundschaft zu diesem Markt, jetzt sind ihnen aber die Frühlingszwiebeln ausgegangen!\n\nSo unscheinbar sie sein mögen, Frühlingszwiebeln sind eine unentbehrliche Zutat beim Kochen. Ohne sie sind Gerichte weniger pikant, haben weniger Geschmack und weniger Aroma.\n\nEs ist eine Katastrophe. Und die nächste Lieferung Frühlingszwiebeln kommt erst nächste Woche!\n\nMoment mal. Ihr seid doch <Bauer/Bäuerin>, oder? Könnt Ihr mir vielleicht helfen?", sourceObjective = "Pflanzt 1 Frühlingszwiebel, erntet sie und bringt dann 5 Frühlingszwiebeln zu Gina Lehmkrall.\n\nFrühlingszwiebelsamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife Frühlingszwiebeln ernten zu können.", progress = "Überseht die Frühlingszwiebel nicht. Sie mag klein und unscheinbar sein, doch sie schmeckt wahrlich phänomenal.", completion = "Ich fasse es nicht! Ich habe zwar schon größere Frühlingszwiebeln gesehen, die hier reichen aber völlig. Ihr habt gerade unsere Haut gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31946] = { id = 31946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mungs Stimme III: Die große Karottenkomödie", description = "Mung-Mung ist egal, wer Karotten stiehlt. Kümmert ihn nur, was Herr Lehmkrall armem Mung-Mung antut, wenn er sieht, dass seine Ernte ruiniert ist!\n\n<Mung-Mung kratzt sich gedankenverloren am Kinn.>\n\nHalt! Mung-Mung hat schlaue Idee. Geh und zieh wachsende saftigleckere Karotten. Dann nehmen wir Karotten und tun so, als wären es die von Herrn Lehmkrall.\n\nJawohl!", sourceObjective = "Pflanzt 2 saftigleckere Karotten, erntet sie und bringt dann 10 saftigleckere Karotten zu Mung-Mung.\n\nSaftigleckere Karottensamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife saftigleckere Karotten ernten zu können.", progress = "Shed-Ling lieben Karotten, aber sie hassen Rüben. Ich hasse Rüben auch.", completion = "Boah, diese Karotten sehen knackig und saftig aus, {name}! Mung-Mung hatte keine Ahnung, dass du so einen grünen Daumen hast.", sourceObjectiveStatus = "unverified-source-field" }
quests[31947] = { id = 31947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer Fungs Stimme III: Zum Wohl mit Kohl", description = "<Bauer Fung strahlt mit einem breiten Lächeln.>\n\nDank Euch habe ich meine kostbaren Yaks wieder! Leider musste ich feststellen, dass die Zeit in freier Wildbahn sie sehr ausgezehrt hat.\n\nAuch, wenn sie ganz ausgehungert sein müssen, kann ich nicht einfach gewöhnliches Gras an meine preisgekrönten Yaks verfüttern.\n\nNicht doch - sie fressen ausschließlich den üppigsten Grünkohl, der hier im Tal gedeiht.\n\nMeine Bestände gehen zur Neige. Wenn Ihr mir etwas Grünkohl für meine Yaks bringen könntet, werde ich Euch fürstlich belohnen.", sourceObjective = "Pflanzt und erntet 3 Grünkohle und bringt dann 15 Grünkohle zu Bauer Fung.\n\nIhr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben. Nach dem Beackern und Pflegen Eurer Pflanze müsst Ihr bis zum nächsten Tag warten, um den reifen Grünkohl zu ernten.", progress = "Ich habe Kosenamen für all meine Yaks. Da gibt es Pelzi, und Wolly; Flauschie und Kuschli und...", completion = "Ich habe Kohl erwartet, aber keinen Kohl dieser Güteklasse! Grundgütiger!\n\nPerfekte runde Form; große, speckige Blätter; herrlich changierende smaragdgrüne Farbe...\n\n<Bauer Fung beißt herzhaft in den Kohl.>\n\nMmm, und dieser süße, frische Geschmack! Das ist ein herrlicher Kohl, {name}. Meine Yaks werden diesen Leckerbissen zu schätzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31948] = { id = 31948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nanas Stimme II: Die Heiligen Quellen", description = "Ihr kommt genau richtig, {name}. Ich will unbedingt frischen Hexenbeeren-Julep machen.\n\nHabt Ihr schon einmal von diesem wundersamen Gebräu gehört?\n\nJeder einzelne Schluck verjüngt Euer Gesicht um zehn Jahre! Was glaubt Ihr, warum ich noch so gut aussehe?\n\nWie dem auch sei, ich brauche eine besondere Zutat - tausend Jahre altes Wasser -, das an der Mündung des Wasserfalls im Norden besorgt werden kann.\n\nIch fürchte, für eine alte Dame wie mich ist die Reise zu beschwerlich, wenn Ihr allerdings einen Krug in die Hände bekommt, werde ich mein Gebräu mit Euch teilen.", sourceObjective = "Benutzt den leeren Krug am Goldfächer, um tausend Jahre altes Wasser zu sammeln.", progress = "Das Wasser in diesem Tal stammt aus dem Tal der Ewigen Blüten im Norden. Angeblich hat das Wasser hier wundersame, magische Eigenschaften.", completion = "Ihr habt die Fälle also gefunden? Oh ja, ich sehe, dass Ihr das Wasser gefunden habt. Großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[31949] = { id = 31949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nanas Stimme III: Hexenbeeren-Julep", description = "Jetzt, wo ich das Wasser habe, kann ich den eiskalten Hexenbeeren-Julep fast schon schmecken!\n\nJetzt müssen wir nur noch ein paar süße Hexenbeeren finden.\n\nDie Beeren meines Enkels waren dieses Jahr völlig unbrauchbar, deshalb muss ich anderswo nach einer vernünftigen Ernte suchen.\n\nIhr habt dieses Jahr nicht zufällig Hexenbeeren angebaut? Wie wär's denn, wenn Ihr mir welche von Eurem Hof bringen würdet?\n\nWenn Eure Beeren den Anforderungen entsprechen, stellen wir eine ganze Ladung von dem alten Gesöff her!", sourceObjective = "Pflanzt 3 Hexenbeeren, erntet sie und bringt dann 15 Hexenbeeren zu Nana Lehmkrall.\n\nHexenbeerensamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife Hexenbeeren ernten zu können.", progress = "Beeilt Euch gefälligst! Ich bin eine alte Frau. Mir bleibt nicht viel Zeit und ich möchte die Soße noch einmal kosten, bevor ich abkratze!", completion = "<Nana Lehmkrall prüft eine dunkle Hexenbeere eingehend und steckt sie dann in den Mund. Ihr Gesicht erhellt sich.>\n\nDas Land lebt! Ich habe schon seit Jahren keine Hexenbeere mehr gegessen, die so süß und saftig war! Der einzige, der solche Beeren angebaut hat, war... der alte Yoon, der Großvater Eures Freundes.\n\n<Nana Lehmkrall wird rot.>\n\nOh, der Mann war vielleicht ein Schlingel! Ich kann mich noch an die Sommertage erinnern, als wir jung und unbeschwert waren und diese Beeren scheffelweise gegessen haben.\n\nDanke, dass Ihr mich an einen alten Freund erinnert habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31951] = { id = 31951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Aki", description = "Ihr habt Euch gegen die Lehrer von Azeroth gut geschlagen. Selbst die Großmeister sind Eurer raffinierten Taktik zum Opfer gefallen.\n\nIch erwarte Euch jetzt im Tal der Ewigen Blüten, denn Ihr habt Euch das Privileg verdient, im Kampf gegen mich anzutreten. Los, {name}, zeigt, ob Ihr das Zeug habt, mich zu bezwingen.", sourceObjective = "Besiegt Aki die Auserwählte in einem Haustierkampf.", completion = "Ihr habt gesiegt. Setzt Eure Ausbildung fort und sucht bei anderen Lehrern wie Euch selbst nach Herausforderungen. Die Reise geht nie wirklich zu Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[31952] = { id = 31952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Pandaria", description = "Jetzt müsst Ihr den zähesten Zähmern in ganz Azeroth gegenübertreten, {name}. Sie haben sich in Pandaria niedergelassen, der Heimat der Großmeister.\n\nSechs Großmeister gibt es noch zu besiegen: Hyuna von den Schreinen im Jadewald, Bäuerin Nishi im Tal der Vier Winde, Mo'ruk in der Krasarangwildnis, den mutigen Yon am Kun-Lai-Gipfel, Sucher Zusshi in der Tonlongsteppe und Ödniswandler Shu in der Schreckensöde.\n\nWenn Ihr glaubt, dass Ihr bereit seid, stellt Euch diesen Meistern ihres Fachs und beweist Euer Können!", sourceObjective = "Besiegt Hyuna von den Schreinen, Bäuerin Nishi, Mo'ruk, Yon den Mutigen, Sucher Zusshi und Ödniswandler Shu in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31953] = { id = 31953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Hyuna", description = "Ihr möchtet erneut einen Kampf wagen? Nun gut. Er wird mich stärker machen, damit ich die geheiligten Stätten meines Volkes noch besser schützen kann.", sourceObjective = "Besiegt Hyuna von den Schreinen in einem Haustierkampf.", completion = "Ihr seid wahrlich stark. Werdet Ihr Eure Fertigkeiten meinen Bemühungen verschreiben?", sourceObjectiveStatus = "unverified-source-field" }
quests[31954] = { id = 31954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Mo'ruk", description = "Diesmal bin ich mit Gewinnen an der Reihe! Wartet's bloß ab!", sourceObjective = "Besiegt Mo'ruk in einem Haustierkampf.", completion = "Nächstes Mal verliert Ihr. Ich werd Euch schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31955] = { id = 31955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Nishi", description = "Die Stärke meiner Haustiere nimmt dank des fruchtbaren Landes, auf dem wir trainieren, immer weiter zu. Ihr habt keine Chance!", sourceObjective = "Besiegt Bäuerin Nishi in einem Haustierkampf.", completion = "Wow! Ich habe wohl nicht alleine trainiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[31956] = { id = 31956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Yon", description = "Wenn Ihr glaubt, dass ich Euch einfach so mit einem anderen Sieg davonkommen lasse, seid Ihr auf dem Holzweg. Dieses Mal werde ich mich als der bessere Trainer erweisen!", sourceObjective = "Besiegt Yon den Mutigen in einem Haustierkampf.", completion = "Schön. Ihr siegt also noch einmal. Jetzt ab mit Euch, ich habe vor unserem nächsten Zusammentreffen einiges an Vorbereitungen zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31957] = { id = 31957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Shu", description = "Ihr wagt Euch also erneut in die Tiefen der Wüste vor, um Euch mir zu stellen - nur werdet Ihr dieses Mal durch die Hand eines wahren Großmeisters zu Boden gestreckt werden. Edelmütig, aber töricht.", sourceObjective = "Besiegt Ödniswandler Shu in einem Haustierkampf.", completion = "In all meinen Jahren als Großmeister habe ich noch nie jemandem mit Eurer Entschlossenheit gegenübergestanden. Die anderen hatten recht, was Euch angeht. Ihr seid eine Größe, mit der man rechnen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[31958] = { id = 31958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Aki", description = "Ihr wollt Euch erneut an mir messen? Nun gut, lasst uns kämpfen.", sourceObjective = "Besiegt Aki die Auserwählte in einem Haustierkampf.", completion = "Ihr seid stärker und Eure Fertigkeiten sind besser ausgeprägt. Eure Reise geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[31959] = { id = 31959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Trick der Kaiserin", description = "Großkaiserin Shek'zeer hat endgültig ihre Geduld mit uns verloren. Wir haben soeben erfahren, dass eine gewaltige Armee sich in den Schatten des Herzens der Angst zusammenzieht, mit dem Befehl, Klaxxi'vess zu vernichten.\n\nWir haben Glück gehabt, dass wir so lange ausgehalten haben, aber gegen eine Belagerung dieses Ausmaßes können wir nichts ausrichten.\n\n<Erwecker/Erweckerin>, Ihr wart von unschätzbarem Wert für uns. Geht, nehmt Euren Platz auf dem Schlachtfeld neben den Getreuen ein.\n\nIch sehe Euch dann auf dem Schlachtfeld!", sourceObjective = "Meldet Euch bei Malik dem Unversehrten vor dem Herzen der Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31966] = { id = 31966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Cataclysm", description = "Ihr habt die besten Zähmer von Nordend bezwungen, doch bevor Ihr es mit den Großmeistern Pandarias aufnehmen könnt, bedarf es weiterer Vorbereitungen. Macht Euch bereit und perfektioniert Eure Fertigkeiten weiter, indem Ihr folgende Zähmer besiegt: Brok in Hyjal, Bordin Ruhigfaust in Tiefenheim und Goz Unheilsfuror im Schattenhochland.\n\nWenn Ihr über sie triumphiert, seid Ihr bereit, die Reise nach Pandaria und Eurer ultimativen Herausforderung entgegen anzutreten.", sourceObjective = "Besiegt Brok, Bordin Ruhigfaust und Goz Unheilsfuror in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31967] = { id = 31967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Cataclysm", description = "Nordend hat sich Euch beugen müssen, doch noch seid Ihr nicht bereit, es mit den Großmeistern Pandarias aufzunehmen. Bezwingt folgende Zähmer, um Euren Willen für die vor Euch liegenden Herausforderungen zu stählen: Brok in Hyjal, Bordin Ruhigfaust in Tiefenheim und Goz Unheilsfuror im Schattenhochland.\n\nErst wenn Ihr sie bezwungen habt, seid Ihr bereit, nach Pandaria aufzubrechen.", sourceObjective = "Besiegt Brok, Bordin Ruhigfaust und Goz Unheilsfuror in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31970] = { id = 31970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Obalis", description = "Ihr glaubt, Ihr seid bereit, Pandaria herauszufordern? Ihr glaubt wirklich, dass Ihr die mächtigsten Zähmer ganz Azeroths bezwingen könnt?\n\nÜberlasst das Urteil darüber nur mir, {race}. Stellt Euch mir auf dem Vir'naaldamm in Uldum, und es wird sich zeigen, ob Ihr wirklich bereit seid.", sourceObjective = "Besiegt Obalis in einem Haustierkampf.", completion = "Ich wurde eines Besseren belehrt. Ihr seid bereit, Euch meinen Meistern zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31971] = { id = 31971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Obalis", description = "Siehe da - <der triumphierende Zähmer/die triumphierende Zähmerin> will <seine/ihre> Kräfte mit den meinen messen. So sei es. Ich nehme die Herausforderung an.", sourceObjective = "Besiegt Obalis in einem Haustierkampf.", completion = "Durch jede meiner Niederlagen gewinne ich an Stärke. Nehmt Euch bei unserer nächsten Begegnung lieber in Acht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31972] = { id = 31972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brok", description = "Noch verstehe ich die Not dieser Geschöpfe nicht genug, um ihnen angemessen Hilfe leisten zu können. Ob ein weiterer Kampf unseren Bund wohl stärken könnte?", sourceObjective = "Besiegt Brok in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31973] = { id = 31973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bordin Ruhigfaust", description = "Die Eingeborenen haben mich die Kraft der Erde gelehrt. Ich weiß um ihre unerschöpfliche Beständigkeit. Lasst uns ein Mal mehr kämpfen, und Ihr werdet sehen, dass ich zäher bin als je zuvor!", sourceObjective = "Besiegt Bordin Ruhigfaust in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31974] = { id = 31974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goz Unheilsfuror", description = "Die Macht des Zwielichts durchdringt mich. Ich bin ein Gott! Ihr habt keine Chance, mich zu besiegen!", sourceObjective = "Besiegt Goz Unheilsfuror in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31975] = { id = 31975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum geht Ihr nicht wieder zu Marlene Trichdie in Sturmwind und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Dann wollen wir sehen... wohin wir Euch als Nächstes senden...", sourceObjectiveStatus = "unverified-source-field" }
quests[31976] = { id = 31976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Die Kunde von Eurem Können verbreitet sich. Ich schlage vor, Ihr kehrt für weitere Unterweisung zu Eurer Trainerin Marlene Trichdie zurück.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31977] = { id = 31977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum kehrt Ihr nicht zu Varzok in Orgrimmar zurück und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ich habe Eure nächsten Herausforderungen vorbereitet, {name}. Zeigt uns, ob Ihr auf sie vorbereitet seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[31978] = { id = 31978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prioritäten!", description = "Seht Euch bloß diese Sauerei an! Das ganze Bräu ist verdorben!\n\nTaran Zhu hat uns davor gewarnt mit Euch Außenseitern zu sprechen, ich nehme aber jede Hilfe an, die ich bekommen kann.\n\nWir waren nach Morgenblüte unterwegs, um unser Bräu abzuliefern, als der Kampf ausbrach. Und jetzt ist unser ganzes Bräu dahin!\n\nWollt Ihr es wiedergutmachen? Vielleicht findet Ihr ja ein paar Fässer mit Honigbräu, die nicht kaputt sind. Dann wäre nicht alles verloren.", sourceObjective = "Findet 6 Fässer mit Honigbräu auf der Honigtaulichtung.", completion = "Es ist nicht so viel wie ich gehofft hatte, doch es wird schon reichen. Hat wohl keinen Sinn, verschüttetem Bräu nachzutrauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31980] = { id = 31980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Die Kunde von Eurem Können verbreitet sich. Ich schlage vor, Ihr kehrt für weitere Unterweisung zu Eurem Trainer Varzok zurück.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31981] = { id = 31981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertroffene Erwartungen", description = "Ab mit Euch zu Eurer Trainerin Marlene Trichdie in Sturmwind. Vielleicht hat sie ein paar... lohnende... Herausforderungen in petto für Euch.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ihr habt wirklich Großmeister Antari bezwungen? Wow! Ich werde ein paar wirklich hartgesottene Zähmer finden müssen, die es mit Euch aufnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31982] = { id = 31982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertroffene Erwartungen", description = "Ab mit Euch zu Eurem Trainer Varzok in Orgrimmar. Vielleicht hat er ein paar... lohnende... Herausforderungen in petto für Euch.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Es gibt nur einen Ort, an dem Eure nächste Prüfung stattfinden könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31983] = { id = 31983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Aufschub", description = "Nicht schlecht, wenn man bedenkt, dass Ihr <ein/eine:r> {race} seid. Und jetzt zurück nach Orgrimmar. Sprecht mit diesem Grobian Varzok. Hoffentlich schickt er Euch an irgendeinen Ort, der sich möglichst weit von meiner Familie entfernt befindet.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ich glaube, ich weiß, was Ihr als Nächstes unternehmen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31984] = { id = 31984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Aufschub", description = "Gute Arbeit, wirklich gute Arbeit! Könntet Ihr wohl Fräulein Marlene Trichdie in Sturmwind darüber berichten?\n\nOh, und bestellt Ihr schöne Grüße von mir. Eine schöne junge Dame wie sie könnte von der Begleitung eines erfahrenen Kämpfers wie mir wirklich profitieren.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Payne hat Euch gebeten, Euch für ihn an mich heranzumachen, stimmt's? Wann begreift er es endlich?", sourceObjectiveStatus = "unverified-source-field" }
quests[31985] = { id = 31985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die triumphale Rückkehr", description = "Ihr seid jetzt so vorbereitet, wie Eure Trainerin das wollte. Kehrt nach Sturmwind zurück und sprecht mit Marlene Trichdie. Sie wird Euch weiter unterweisen.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ihr habt also Obalis kennengelernt? Unter seiner rauen Schale ist er ein toller Bursche.", sourceObjectiveStatus = "unverified-source-field" }
quests[31986] = { id = 31986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die triumphale Rückkehr", description = "Ihr seid jetzt so vorbereitet, wie Euer Trainer das wollte. Kehrt nach Orgrimmar zurück und sprecht mit Varzok. Er wird Euch weiter unterweisen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ihr seid jetzt auf eine echte Prüfung Eures Könnens im Kampf vorbereitet. Seid Ihr soweit?", sourceObjectiveStatus = "unverified-source-field" }
quests[31987] = { id = 31987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore" }
quests[31988] = { id = 31988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliche Szenarioauswahl" }
quests[31989] = { id = 31989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel der Ruhe - Schließt Eure Ausbildung ab", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung abzuschließen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", sourceObjective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31991] = { id = 31991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Zusshi", description = "Ich wusste, dass Ihr zurückkommen würdet, um noch einmal gegen mich anzutreten. Dann wollen wir sehen, wer im Kampf weiser ist.", sourceObjective = "Besiegt Sucher Zusshi in einem Haustierkampf.", completion = "Ihr seid tatsächlich überlegen. Wenn Ihr mich entschuldigen würdet - ich muss den See um Rat zu meiner Niederlage bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31998] = { id = 31998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Zweifels", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in den Tempel der Jadeschlange führen. Aktiviert die Kugel des Herausforderers und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Tempel der Jadeschlange im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31999] = { id = 31999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrims Befehl", description = "Ihr habt hier eine schöne Basis. Von der Allianz ist weit und breit nichts zu sehen, und dazu habt Ihr noch einige Veteranen der Horde zur Seite. Ich würde sagen, es ist an der Zeit, diesen Kontinent rot zu färben.\n\nGeneral Nazgrim wird wissen, wie unser erster Schritt aussieht.", sourceObjective = "Meldet Euch bei General Nazgrim auf dem Starkarmflugplatz im Jadewald.", completion = "Wir mögen zwar die Schlacht gegen die Allianz gewonnen haben, aber das bringt uns mit den ganzen Plapperaffen in unserem Gebiet auch nicht weiter.\n\nDie Ho-zen sind unser nächstes Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32000] = { id = 32000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Yan-Zhu der Dekantierte", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in die Brauerei Sturmbräu führen. Aktiviert die Kugel des Herausforderers und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Brauerei Sturmbräu im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32001] = { id = 32001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Hasses", description = "{name}, Ihr müsst eine abgeklärte Gruppe zusammenstellen und sie ins Shado-Pan-Kloster führen. Aktiviert die Kugel des Herausforderers und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Shado-Pan-Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32002] = { id = 32002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Xin der Waffenmeister", description = "{name}, Ihr müsst eine geschickte Gruppe zusammenstellen und sie in den Mogu'shanpalast führen. Aktiviert die Kugel des Herausforderers und bereitet Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Mogu'shanpalast im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32003] = { id = 32003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Raigonn", description = "{name}, Ihr müsst eine entschlossene Gruppe zusammenstellen und sie zum Tor der Untergehenden Sonne führen. Aktiviert die Kugel des Herausforderers und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Tor der Untergehenden Sonne im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32004] = { id = 32004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Schwadronsführer Ner'onok", description = "{name}, Ihr müsst eine scharfsichtige Gruppe zusammenstellen und sie zur Belagerung des Niuzaotempels führen. Aktiviert die Kugel des Herausforderers und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Niuzaotempel im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32005] = { id = 32005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Durand", description = "{name}, Ihr müsst eine tapfere Gruppe zusammenstellen und sie in das Scharlachrote Kloster führen. Aktiviert die Kugel des Herausforderers und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Scharlachrote Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32006] = { id = 32006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Flammenwirker Koegler", description = "{name}, Ihr müsst eine gewitzte Gruppe zusammenstellen und sie in die Tiefen der Scharlachroten Hallen führen. Aktiviert die Kugel des Herausforderers und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.", sourceObjective = "Schließt die Scharlachroten Hallen im Herausforderungsmodus ab.", completion = "Hervorragende Leistung, {name}. Allein der Gedanke daran, wie er die schöne Bibliothek niederbrennt, jagt mir einen kalten Schauer den Rücken hinab. Eure Freunde werden beeindruckt sein, wie schnell Ihr ihn ausgeschaltet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32007] = { id = 32007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Dunkelmeister Gandling", description = "{name}, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Scholomance führen. Aktiviert die Kugel des Herausforderers und reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt Scholomance im Herausforderungsmodus ab.", completion = "{name}, Ihr habt uns einen großen Dienst erwiesen. Hoffen wir, dass die Gebeine der Toten endlich in Frieden ruhen können, nun, da Gandling sie nicht mehr stören wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[32008] = { id = 32008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlene Trichdie", description = "Seid gegrüßt, {name}! Ich bin Marlene Trichdie. Man hört in letzter Zeit ziemlich viel von Euch. Ihr scheint zu <einem hervorragenden Zähmer/einer hervorragenden Zähmerin> heranzureifen!\n\nIhr solltet Euch mit mir in Sturmwind auf ein Gespräch treffen. Ich stehe mit den besten Zähmern in ganz Azeroth in Verbindung und kann Euch helfen, noch besser zu werden!", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ach, Ihr seid {name}. Wunderbar! Dann machen wir uns gleich an die Arbeit, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[32009] = { id = 32009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Lok'tar, {name}. Mein Name ist Varzok, und ich habe in letzter Zeit viel von Euren Leistungen als <Zähmer/Zähmerin> gehört. Ich möchte Euch gerne Trainern in ganz Azeroth vorstellen, damit Ihr Eure Fertigkeiten weiter verbessern könnt.\n\nBitte trefft Euch auf ein Gespräch mit mir in Orgrimmar, auf dass wir alles in die Wege leiten können.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ihr müsst {name} sein. Schön, Eure Bekanntschaft zu machen. Ich bin Varzok.\n\nIch werde von nun an Eure Kontaktperson sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32010] = { id = 32010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Aufgabe", description = "Kennt Ihr die Himmlischen Erhabenen? Yu'lon, Chi-Ji, Xuen und Niuzao wachen über die vier Regionen Pandarias.\n\nAuch über Euch.\n\nIhr Wissen ist uralt und von großer Macht. Jenen, die sie für würdig erachten, vermögen sie ungeheure Macht zu verleihen.\n\nIhr mögt danach streben, ihr Vertrauen zu gewinnen, doch sie brauchen Euch für eine weitaus wichtigere Aufgabe.\n\nDas Tal der ewigen Blüten ist in Gefahr. Zuerst müssen wir es verteidigen. Dann richten wir unseren Blick auf die Himmlischen selbst.", sourceObjective = "Einen respektvollen Ruf beim Goldenen Lotus erlangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32011] = { id = 32011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Aufgabe", description = "Kennt Ihr die Himmlischen Erhabenen? Yu'lon, Chi-Ji, Xuen und Niuzao wachen über die vier Regionen Pandarias.\n\nAuch über Euch.\n\nIhr Wissen ist uralt und von großer Macht. Jenen, die sie für würdig erachten, vermögen sie ungeheure Macht zu verleihen.\n\nIhr mögt danach streben, ihr Vertrauen zu gewinnen, doch sie brauchen Euch für eine weitaus wichtigere Aufgabe.\n\nDas Tal der Ewigen Blüten ist in Gefahr. Zuerst müssen wir es verteidigen. Dann richten wir unseren Blick auf die Himmlischen selbst.", sourceObjective = "Einen respektvollen Ruf beim Goldenen Lotus erlangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32016] = { id = 32016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrwürdige Amulette des Glücks", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem ehrwürdigen Amulett des Glücks werden wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 50 geringe Amulette des Glücks.", progress = "Mögen diese Talismane Euch Glück bringen, {name}.", completion = "Mögen die Sterne mit einem Lächeln auf Euch herabblicken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32017] = { id = 32017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrwürdige Amulette des Glücks", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem ehrwürdigen Amulett des Glücks werden wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 50 geringe Amulette des Glücks.", progress = "Mögen diese Talismane Euch Glück bringen, {name}.", completion = "Mögen die Sterne mit einem Lächeln auf Euch herabblicken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32018] = { id = 32018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Name war Sturmbräu", description = "Ein außergewöhnlicher Pandaren machte vor einigen Tagen Zwischenstation in der Stadt. Er erzählte bessere Geschichten als Pan, trank doppelt so viel wie Li und hat mich zum Abschluss noch vor der Taverne verprügelt. Und nebenher hat sich seine kleine Nichte über uns lustig gemacht.\n\nEs war einfach toll.\n\nSie sagten, dass sie ins Tal der Vier Winde reisen wollten. Ihr solltet ihn kennenlernen! Hütet Euch nur vor seinem rechten Haken.", sourceObjective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", completion = "Ha ha! Bolo hat Euch geschickt? Der \"Fassflüsterer\", stimmt's? Aus dem Betrunkenen Ho-zen?\n\nWie geht es seinem Auge? Und ist sein Freund immer noch verkatert?\n\nAch, das war mal ein schöner Abend.", sourceObjectiveStatus = "unverified-source-field" }
quests[32019] = { id = 32019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn Sturmbräu", description = "Die Lage war nicht immer so, {race}. Oh nein, sie war sogar noch viel schlimmer. Vor gerade einmal drei Wochen wurden wir von Saurokbanditen belagert. Sie haben unsere Jade gestohlen, unsere Nahrungsmittelvorräte besudelt und unsere Jungen terrorisiert.\n\nWir brauchten einen Helden, und der sollte auch kommen.\n\nEr schlug ihre Streitkräfte zurück, besiegte ihren Anführer und brachte uns die gestohlene Jade zurück. Und zum Dank wollte er nichts weiter als einen Schlangenritt für seine Nichte.\n\nIch hatte nie die Gelegenheit, ihm richtig zu danken. Wenn Ihr ins Tal der Vier Winde geht, könntet Ihr ihm unseren Dank ausrichten?", sourceObjective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", completion = "Ihr kommt vom Tempel der Jadeschlange? Ren-Zhu lässt seinen Dank ausrichten?\n\nNun, äh... es war wirklich nichts. Ich hätte diesen Saurok besiegen können, ohne einen Tropfen Bräu zu verschütten.\n\nIch glaube, das habe ich sogar.", sourceObjectiveStatus = "unverified-source-field" }
quests[32020] = { id = 32020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
