quests[32030] = { id = 32030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal in hundert Lebzeiten", description = "Die Zeit ist gekommen, <Erwecker/Erweckerin>.\n\nMit der vereinten Macht des Rates werden wir dieser verderbten Kaiserin ein Ende bereiten.\n\nDieses Ritual wurde schon seit hunderten Lebzeiten Eurer Art nicht mehr gesehen - und noch nie zuvor von einem Außenstehenden.\n\nIm Gegenzug für die Dienste, die Ihr uns erwiesen habt, lade ich Euch nun ein, diesen wichtigen Augenblick unserer Geschichte mitzuerleben.", sourceObjective = "Sprecht mit Klaxxi'va Ik in Klaxxi'vess.", completion = "Der Zeitpunkt Eurer Ankunft ist gut gewählt, Erwecker.\n\nUnser Ritual hat begonnen.", sourceObjectiveStatus = "unverified-source-field" }
