quests[32034] = { id = 32034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
quests[32035] = { id = 32035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seide macht's!", description = "Von den Seidenfeldern hört man merkwürdige Geräusche.\n\nUnd auch seltsame Gerüche ziehen von dort herüber.\n\n<Ein abgebrannter/Eine abgebrannte:c> {class} wie Ihr könnte ihnen vielleicht etwas aushelfen und sich dabei ein paar Goldstücke verdienen.\n\n... Oder auch nicht.", sourceObjective = "Meldet Euch bei Seidenmeister Tsai auf den Seidenfeldern im Tal der Vier Winde.", completion = "Seid gegrüßt, {class}. Willkommen in den Seidenfeldern.", sourceObjectiveStatus = "unverified-source-field" }
quests[32036] = { id = 32036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten" }
