quests[32038] = { id = 32038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirschmeister", description = "Für eine schöne Hirschjagd bin ich immer zu haben. Es sind zähe und schnelle Tiere, die ihr Revier verteidigen.\n\nSie mögen zwar Pflanzenfresser sein, doch können sie selbst den erfahrensten Jäger in die Flucht schlagen.\n\nÖstlich von hier ist ein ganzes Rudel Wildlandhirsche, das nur darauf wartet von <einem Jäger/einer Jägerin> wie Euch etwas aufgescheucht zu werden.\n\nGute Jagd!", sourceObjective = "Tötet 10 Wildlandhirsche.", completion = "Eine so gute Hirschjagd habe ich seit dem Eschental nicht gesehen.", sourceObjectiveStatus = "unverified-source-field" }
