quests[32105] = { id = 32105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloses Kassenbuch eines Architekten", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", sourceObjectiveStatus = "unverified-source-field" }
quests[32106] = { id = 32106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[32107] = { id = 32107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegender Tigergurami", description = "Ihr habt einen einzigartigen Fisch gefangen... mit Flügeln. Vielleicht solltet Ihr Nat Pagle bei der Anlegestelle der Angler nach seiner Expertenmeinung fragen.", sourceObjective = "Bringt den fliegenden Tigergurami zu Nat Pagle an der Anlegestelle der Angler.", sourceObjectiveStatus = "unverified-source-field" }
quests[32108] = { id = 32108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrschaftsfeste", description = "Jetzt ist es an der Zeit, diesem neuen Land die wahre Stärke der Horde zu zeigen.\n\nKehrt zur Landestelle zurück und setzt das verbleibende Signalfeuer in Brand. Unsere Flotte wartet.", sourceObjective = "Zündet das Signalfeuer am Strand der Landezone der Horde an, um der Flotte ein Zeichen zu senden.", completion = "<Dieses Feuer wird der gesamten Invasionsflotte der Horde das Signal geben, an diesem Strand an Land zu gehen und Garroshs Feldzug in Pandaria zu beginnen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32109] = { id = 32109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löwenlandung", description = "Die Horde darf schon viel zu lange frei in Azeroth herumlaufen. Ich lasse nicht zu, dass dieses neue Land von irgendeinem barbarischen \"Kriegshäuptling\" erobert wird.\n\nSeid Ihr bereit, Pandaria die Gerechtigkeit der Allianz zu bringen?\n\nKehren wir zur Landezone zurück. Benutzt den Raketenzünder, um die Flotte richtig an Land zu bringen und leitet Operation Schildwall ein.", sourceObjective = "Signalisiert der Flotte der Allianz in der Krasarangbucht mit einem Abschussgerät für Leuchtfeuer.", completion = "<Blaue Segel, die am Horizont kaum sichtbar sind – die gesamte Macht der Allianzflotte, die auf ein letztes Signal wartet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32114] = { id = 32114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Du willst also tägliche Quests ausprobieren?", description = "Du willst tägliche Quests ausprobieren? In Ordnung." }
quests[32115] = { id = 32115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fesseln der Vergangenheit", description = "Die Mogu sind ein Haufen Dreckskerle!\n\nSie haben die Pandaren, die in diesen Höhlen arbeiteten, selbst nach ihrem Tod noch versklavt. Befreit ihre Geister! Es ist einfach nicht gerecht.\n\nSeid aber vorsichtig... sie sind so traumatisiert, dass sie Freund und Feind nicht voneinander unterscheiden können. Also werden sie sich vermutlich wehren.", sourceObjective = "Befreit 14 aufgewühlte Sklavengeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[32116] = { id = 32116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prioritäten vonnöten!", description = "Als ich die Grabung des Tunnels nach Nordwesten anordnete, dachte ich, wir würden etwas Nützliches finden. Gold, Eisen... irgendwas!\n\nStattdessen fanden wir Moguartefakte und ich darf einen Haufen Zwerge von der Forscherliga hüten.\n\nWie ich von den Soldaten höre, gibt es in den Minen Probleme. Ich habe Befehl von Wrynn, die Forscherliga zu unterstützen, habe aber keine Soldaten übrig. Würdet Ihr hinuntergehen und herausfinden, was da los ist?", sourceObjective = "Trefft Euch mit Hilda Hornsturz bei den Ruinen von Ogudei in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32118] = { id = 32118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Vorteil nutzen", description = "Die Dummköpfe von der Forscherliga haben im Nordosten eine antike Moguruine ausgegraben. Und in ihrer Tollpatschigkeit – natürlich – die Geister der Mogu in ihrem Inneren aufgebracht.\n\nWir werden uns ihre Unfähigkeit zunutze machen. Nehmt dieses Portal und trefft Euch mit Kaelis Segelstrahl, meinem Kontakt in den Ruinen.", sourceObjective = "Benutzt das Portal im Außenposten Zündmine, um Euch bei den Ruinen von Ogudei in der Krasarangwildnis mit Kaelis Segelstrahl zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32120] = { id = 32120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis von Ogudei", description = "Die Ruinen, die wir besetzen, wurden von Ogudei errichtet – einem Moguherrscher der Antike. Wir wissen kaum etwas über ihn, doch die Zunahme der Geister in diesem Gebiet deutet darauf hin, dass ein Zusammenhang mit der Geisterbindung besteht.\n\nWenn Ihr diese Geister vernichtet, bleibt ein kleiner Rückstand ihrer Essenz in dieser Welt zurück. Bringt uns diesen – wir werden ihn analysieren und hoffentlich mehr über Ogudeis Geschichte und seine Macht herausfinden.", sourceObjective = "Sammelt 5 uralte Moguessenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32121] = { id = 32121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geisterfalle", description = "In der Ruine gibt's 'ne Menge richtig widerlicher blauer Kristalle. Schaut sie falsch an, dann rennen Euch ein paar verflucht wütende Geister hinterher.\n\nIhr müsst für mich hineingeh'n und ein paar von ihnen loswerden, damit wir die Leute wieder hierher zum Arbeiten zurückbringen können.", sourceObjective = "Zerstört 3 Geisterfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32122] = { id = 32122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogudeis Leutnants", description = "Nachdem wir uns zu einem alten Abschnitt der Moguruinen durchgegraben hatten, fing diese üble Geschichte an – das war auch der Zeitpunkt, als die zwei schlimmsten Geister auftauchten.\n\nSie müssen verschwinden, <mein Freund/meine Beste>.", sourceObjective = "Tötet Meng-do, die Stärke des Berges und Gen-li, Verdreher von Worten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32123] = { id = 32123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod auf zwei Beinen", description = "Die Allianz hat das Festland erreicht. Wenn wir sie hier nicht besiegen, ist jegliche Hoffnung auf eine Präsenz der Horde auf diesem Kontinent verloren.\n\nBegebt Euch zu dem Schlachtfeld südlich von hier und tötet alle Mitglieder der Allianz, die Ihr findet.\n\nZeigt ihnen, dass jedes Mitglied der Horde, das noch aufrecht auf zwei Beinen steht, zehn Allianzler erledigen kann!", sourceObjective = "Besiegt 10 Soldaten der Allianz in der Herrschaftsfeste.", completion = "Gut gemacht, {name}. Wie ich sehe, hat Euch der Aufenthalt in diesem Land in Eurem Vorsatz bestärkt und Eure Fertigkeiten verbessert.", sourceObjectiveStatus = "unverified-source-field" }
quests[32126] = { id = 32126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt, was Ihr könnt", description = "Die Allianz mag zwar feige sein, dumm ist sie aber nicht. Gegen schwächere Wesen gerichtet wäre ihr Angriff furchtbar.\n\nUm die Belagerung weiterzuführen und Druck auf unsere Truppen auszuüben, wirft sie zur Unterstützung ihrer Bodentruppen Vorräte aus der Luft ab.\n\nSucht die Strände und Docks im Süden nach abgeworfenen Vorräten ab und zerstört sie.\n\nDie Allianz soll sehen, wie ihre Nahrungs- und Munitionsvorräte vor ihren Augen vernichtet werden, und verzweifeln.", sourceObjective = "Zerstört 8 Versorgungsgüter der Allianz.", completion = "Denkt daran, dass die Waffe Eurer Wahl nicht immer die Waffe mit der größten Reichweite oder dem meisten verursachten Schaden ist. Im Endeffekt ist die beste Waffe diejenige, die jedes Mal funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[32127] = { id = 32127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tot, alle tot", description = "Unser Kriegshäuptling hat mich an diese Küste entsandt, damit ich mich um diese jämmerliche Bedrohung durch die Allianz kümmere.\n\nDiese Menschen und ihre Verbündeten haben sich als ausgesprochen abhängig von ihren Anführern erwiesen. Keinerlei Eigeninitiative.\n\nWenn Ihr heute das Schlachtfeld überquert, seht Euch die Schiffe der Allianz vor unserer Südküste an. Findet ihre Kapitäne.\n\nTötet sie.\n\nFür die Horde!", sourceObjective = "Besiegt Kapitän Brent der Schwarze und Kapitän Mulkey.", completion = "Die Allianz ihrer Anführer zu berauben reicht nicht. Wir müssen jene, die nach der Führung trachten, vor dem Preis eines solchen Ansinnens warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32128] = { id = 32128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder beißt einer ins Gras", description = "Die Allianz hat sich vor unserer Südküste breitgemacht und beschießt unsere Bodentruppen kontinuierlich mit Kanonenfeuer. Sehen wir doch, wie toll ihre Belagerung ohne diese Unterstützung ist.\n\nBegebt Euch an Bord der feindlichen Schiffe und zerstört ihre Munitionsreserven. Das wird ihnen die Zähne ziehen.", sourceObjective = "Jagt die explosive Ladung der Kühnheit und der Klinge der Tapferkeit in die Luft.", completion = "Ah! Seht Euch an, wie sie brennen. Um diese neuen Schiffe der Allianz dauerhaft zu zerstören, ist allerdings mehr nötig. Ich bin mir sicher, dass sie die Feuer in ein, zwei Tagen gelöscht haben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32129] = { id = 32129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliche Verteidigung 06" }
quests[32130] = { id = 32130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Glück, viel Spaß", description = "Ich habe da ein paar Kunden, die gute, altmodische Ohren sammeln möchten. Nicht einfach irgendwelche Ohren. Sie sind nur an Ohren mit der absolut größten Menge Ohrenschmalz interessiert, die es für Geld zu kaufen gibt! \n\nSie glauben wohl, das würde Glück bringen oder so.\n\nJedenfalls möchte ich, dass Ihr welche für mich besorgt. Ich will aber nicht, dass Ihr Tiere quält, deshalb sollt Ihr sie von der Allianz in der Löwenlandung drüben besorgen.\n\nAmüsiert Euch gut – und vergesst nicht, mir nur die schmalzigsten zu bringen!", sourceObjective = "Sammelt 10 besonders schmalzige Allianzohren in der Löwenlandung in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32131] = { id = 32131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen mehr Mineralien", description = "Die Gnome graben einen Steinbruch im Nordosten.\n\nSie verwenden das Material für den Bau!\n\n<Zazzix verdreht die Augen.>\n\nSie sind zu dumm, dabei zu merken, dass es spezieller Mogustein zur Herstellung belebter Statuen ist. \n\nWIR können ihn mit etwas magischem Goblinsaft mixen und richtig große Explosionen damit bewirken!\n\nDie Teile sind aber schwer. Sie benutzen zum Ausgraben der Steine ein paar von ihren dummen Bombenbots. Wenn Ihr die in der Nähe von Steinplatten in die Luft jagt, bekommt Ihr Stücke, die klein genug zum Tragen sind. \n\nOder tötet sie einfach und greift sie euch. Was auch immer besser funktioniert.", sourceObjective = "Besorgt 20 Brocken belebbaren Steins aus dem Steinbruch der Löwenlandung. Ihr findet sie bei Ingenieuren der Löwenlandung, die sie tragen, oder Ihr könnt Steinplatten mithilfe von Kollateralschaden in tragbare Brocken sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32132] = { id = 32132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiterschikane", description = "Unseren Goblinfreunden fehlt leider das erforderliche Strategieverständnis zum Gewinnen eines langwierigen Konflikts.\n\nDer Schlüssel bei der Eliminierung einer ständigen Präsenz liegt darin, ihre Fähigkeit zum Aufstocken und Wiederaufbau ihrer Truppen zu attackieren.\n\nIn diesem Fall bedeutet das, ihre Arbeiter auszuschalten. Tötet sie und schwächt das Fundament. Dann wird der Rest der Festung verfallen.", sourceObjective = "Tötet 30 Arbeiter der Löwenlandung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32133] = { id = 32133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächterschutz", description = "Wir haben über ihrer Basis schwere Luftunterstützung in der Gestalt von viel zu vielen Zwergen auf viel zu vielen Greifen entdeckt. Das bedeutet, wir können keinen Überblick von oben über das Gebiet bekommen.\n\nEin Troll... ein Freund von mir hat uns einen Satz Wächterschutze gegeben, mit denen wir ihre Basis ausspionieren und uns einen Überblick darüber verschaffen können, was da drinnen abläuft.\n\nSchlechte Nachrichten, <mein Freund/meine Liebe> – das Vergnügen da hineinzugehen gebührt Euch.", sourceObjective = "Stellt auf den Docks, im Rathaus und im zweiten Geschoss der Kaserne in der Löwenlandung Wächterschutze auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32134] = { id = 32134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hart gekontert", description = "Es ist uns gelungen, ein paar Verwüster an den Strand zu bekommen. Diese idiotischen Zwerge mit ihren idiotischen Mörserrohren sind aber auch dort draußen und hindern die Verwüster am Vorstoßen und daran, die Festung selbst anzugreifen!\n\nGeht da raus, tötet ein paar Zwerge und jagt ein paar Mörserrohre in die Luft.", sourceObjective = "Tötet 8 Mörserteamingenieure der Löwenlandung und zerstört 2 Mörserrohre der Löwenlandung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32135] = { id = 32135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenmörder", description = "Es gibt Situationen, in denen einen von ihren Soldaten auszuschalten wichtiger ist als Hunderte zu töten.\n\nSie haben einige ihrer Helden auf dem Schlachtfeld aufmarschieren lassen, damit sie ihre Verteidiger unterstützen. Sie zu töten wird nicht nur ihre Verteidigung aufweichen sondern sich auch auf ihre Moral niederschlagen.\n\nBrecht also auf und zieht einen für mich aus dem Gefecht. Ihr schafft das.", sourceObjective = "Tötet einen Helden der Allianz an der Löwenlandung in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32138] = { id = 32138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Holz", description = "Jeden Tag dasselbe! \"Das ist uns ausgegangen!\", \"Wir brauchen mehr davon!\", \"Warum rührt Ihr nie einen Finger?!\"\n\nIch arbeite! Ich erledige Dinge! Sie können so verletzend sein! Ich gebe hier unten mein Bestes!\n\nAch ja, wir brauchen mehr Holz! Geht hinunter und richtet diesem Nichtsnutz Zino aus, dass er seine Schredder anwerfen soll!", sourceObjective = "Findet Zino \"den Schredder\" Blitzbeil auf dem Holzhof.", sourceObjectiveStatus = "unverified-source-field" }
quests[32139] = { id = 32139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestapelt!", description = "Wir haben erst heute Morgen eine Bestellung abgewickelt. Sie können doch unmöglich schon mehr brauchen?!\n\nMein Team hat Doppelschichten gearbeitet, um diese Bäume zu fällen und zu verarbeiten.\n\nDas Problem ist, dass wir es hier unten mit einer Plage von Truppen aus der Löwenlandung zu tun haben. Ich habe heute schon einmal Kopf und Kragen riskiert und bin nicht bereit, noch einmal da rauszugehen!\n\nGoob wird Euch begleiten und mit dem Auftrag helfen. Er ist zwar nicht der Hellste, dafür kann er schwer heben.", sourceObjective = "Sammelt 9 Stücke Bauholz der Herrschaftsfeste auf dem Holzhof.", sourceObjectiveStatus = "unverified-source-field" }
quests[32140] = { id = 32140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Eisen", description = "Als sie sagten, sie hätten ein paar unglaubliche Gesteinsbrocken in der Mine gefunden, habe ich mir Diamanten vorgestellt. Jedes Kind weiß doch, dass alle Minen voller Diamanten sind, Dummchen! Oder zumindest Rubine!\n\nStattdessen habe ich nur dieses komische Eisen bekommen. Was soll ich denn damit anfangen?\n\nTja, keiner hat je behauptet, dass diese Arbeit glamourös wäre. Ich tue, was ich kann, um ihr ein wenig Klasse zu verleihen.\n\nWir haben gerade einen neuen Arbeitsauftrag für Eisen erhalten. Sucht Daxil vor Erzschleifs Grabung auf und erledigt ihn, pronto!", sourceObjective = "Findet Daxil \"Klunker\" Erzschleif bei Erzschleifs Grabung.", completion = "Beschwert sie sich noch immer über Diamanten und Rubine? Wir haben hier unten etwas Besseres als Diamanten gefunden!\n\nDieses Erz ist etwas Besonderes. Es hat Potenz!", sourceObjectiveStatus = "unverified-source-field" }
quests[32141] = { id = 32141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energetisches Metall", description = "<Daxil kneift ihre Augen zusammen und spricht mit gedämpfter Stimme.>\n\nManchmal graben wir zu tief, {class}. Manchmal fördern wir etwas so Grauenhaftes zutage, dass wir uns wünschen, wir hätten mit dem Graben nie angefangen...\n\nIch mache nur Spaß! Also, versteht mich nicht falsch, wir haben tatsächlich etwas Unerwartetes gefunden. Das Erz, das wir dort unten finden, ist nicht Euer normales Nullachtfünfzehn-Eisen.\n\nEs gibt dabei nur ein Problem: Schieferspinnen! Wir haben große Mühe, diesen Bestellungen nachzukommen.\n\nKönnt Ihr vielleicht mit anpacken?", sourceObjective = "Besorgt 7 aufgeladene Eisenerzklumpen aus Erzschleifs Grabung.", progress = "Habt Ihr vielleicht etwas Funkelndes dort unten gefunden?", completion = "Haben sie dort unten etwas Brauchbares gefunden? Vielleicht einen Smaragd oder einen Opal? Ist es zu viel verlangt, ein bisschen Einsatz zu fordern?!\n\nWie dem auch sei! Ich werde dafür sorgen, dass diese Lieferung ihren Bestimmungsort erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32142] = { id = 32142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis zum felsigen Ende", sourceObjective = "Tötet 10 Orcs an der Herrschaftsfeste.", completion = "Gut gemacht, Soldat. Das sollte dabei helfen, die Horde in Schach zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32143] = { id = 32143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkund-o-magie", sourceObjective = "Findet die drei Erkund-o-meter in der Herrschaftsfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[32144] = { id = 32144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Hochdruck", description = "Die Horde ist über alle Maßen stolz und wird bedenkenlos bis zum Tod kämpfen.\n\nWir müssen ihren Willen brechen, ohne dabei selbst riesige Verluste zu erleiden.\n\nSucht an der Küste und in der Nähe ihrer Schiffe nach ihren Vorräten. Zerstört sie.\n\nNichts bricht den Willen eines Verteidigers schneller als mit anzusehen, wie seine Hoffnung auf Nahrung sich in Rauch auflöst.\n\nWenn Ihr damit fertig seid, sucht Sully hinter den feindlichen Linien auf. Er hat den nächsten Auftrag für Euch.", sourceObjective = "Zerstört 8 Vorratskisten der Horde.", completion = "Dank Eurer Aktionen weiß die Horde, dass sie ihre Truppen nicht ernähren kann.\n\nDie Dauer, die sie einer Belagerung standhalten kann, ist erheblich reduziert, und bald wird ihre Moral darunter leiden.\n\nWir dürfen nicht aufhören, Druck auszuüben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32145] = { id = 32145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld", description = "Meine Sonden haben drei sehr gefährliche Ziele im Hof des Herrschaftsturms entdeckt.\n\nEs handelt sich um einen Abgesandten der Oger, einen Offizier der Kor'kron und einen geistesgestörten Goblin-Bombenbauer.\n\nMeine Belager-o-matiks sind nicht für den Kampf Mann gegen Mann konzipiert, die Eliminierung der Ziele ist also Eure Aufgabe.\n\nViel Glück! Erstattet mir anschließend auf der Himmelsfeuer Bericht.", sourceObjective = "Besiegt Steingardistin Ruk'ra, Bombentechniker Klickefritz und Or'Dac.", completion = "Gute Arbeit! Es tut mir leid, gute Soldaten Gefahren auszusetzen, doch mein Auto-Verwüst-o-mat V2 ist noch nicht funktionstüchtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[32146] = { id = 32146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Hämmer", description = "Die Horde scheint zu glauben, sie könne sich hinter ihren schlagkräftigen Schergen verstecken.\n\nDie Schergen sind zäh, stark und dümmer als ein verkaterter Oger.\n\nBegebt Euch dort hinunter und lasst den Hammer des Zorns der Allianz auf sie niedergehen!", sourceObjective = "Tötet 5 schwere Schergen.", completion = "Ich danke Euch, Soldat. Das sollte die Horde lehren, dass mehr als ein paar Schergen nötig sind, um uns zu verjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32147] = { id = 32147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher Angriff 06" }
quests[32148] = { id = 32148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff! Bewegung!", description = "Klar, sie haben jede Menge Grunzer da draußen, die an unsere Tür hämmern und nur darauf warten, uns die Köpfe abzuschneiden.\n\nAber die Grunzer bereiten mir keine Sorgen. Sie verfügen auch über Schamanen und Räuber. Die Schamanen stärken mit ihrer Magie die Grunzer, die Räuber sind schnell und auf das Ausschalten unserer Gebäude spezialisiert.\n\nIch möchte, dass Ihr da rausgeht und ein paar von den Schamanen und Räubern erledigt.\n\nLos! Angriff! Bewegung!", sourceObjective = "Tötet 12 Schamanen oder Räuber der Herrschaftsoffensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[32149] = { id = 32149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcen sammeln", description = "Ach, die armen Arbeiter...\n\nJa, natürlich sind sie Feiglinge. Sie wissen aber nicht, wie man kämpft, und sie ziehen los, um Holz für uns zu sammeln... die Horde attackiert sie... Es ist einfach furchtbar!\n\nWir brauchen das Holz aber, wenn wir durchhalten wollen. Geht los und sammelt sämtliches Holz, das sie fallengelassen haben.", sourceObjective = "Besorgt 12 Stücke Bauholz der Löwenlandung, die Ihr von den Stapeln fluchtartig aufgegebenen Bauholzes bergt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32150] = { id = 32150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgungsblockade", description = "Die Horde hat beschlossen, Goblins die Verantwortung für ihre Logistik zu übertragen. Und wo es Goblins gibt, da gibt es auch achtlos platzierten Sprengstoff.\n\nSpäher berichten, dass ihre Vorräte in Karren sind, die außerdem auch noch Verwüstermunition enthalten. Seht diese Kisten nur schief an und sie fliegen in die Luft. \n\nWenn wir genügend Ressourcen der Horde zerstören, können wir ihren Angriff verkürzen und dadurch Leben retten. Geht also los und zieht diese Karren aus dem Verkehr!", sourceObjective = "Zerstört 8 Versorgungskarren der Herrschaftsfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[32151] = { id = 32151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turmverteidigung", description = "Die Gnome betreiben unseren Steinbruch im Nordwesten. Der Fels ist besonders hart – den Gnomen zufolge bauten die Mogu damit ihre Konstrukte. \n\nOb das stimmt, weiß ich nicht. Ich weiß allerdings, dass wir mit diesem Stein unsere Türme bauen und dass die Horde die Bilgewässer-Goblins angewiesen hat, ihn uns zu stehlen.\n\nMacht Euch auf und holt etwas davon zurück. Übrigens, Kollateralschaden bricht möglicherweise die Steinplatten in Stücke. Nehmt in diesem Fall die Stücke auch mit.", sourceObjective = "Besorgt 20 Brocken belebbaren Steins aus dem Steinbruch der Löwenlandung von Bilgewässer Goblins oder indem Ihr Steinplatten mit Kollateralschaden zerstört.", sourceObjectiveStatus = "unverified-source-field" }
quests[32152] = { id = 32152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsschaden", description = "Die Horde hatte den genialen Einfall, die Bilgewässer Goblins unseren Steinbruch angreifen zu lassen.\n\nSie verwenden schweren Sprengstoff – schweren Sprengstoff, der mit der Munition in ihren Verwüstern reagieren wird.\n\nTötet Bilgewässer Goblins, bis Ihr Sprengstoff findet, platziert ihn an einem der Verwüster... und BUMM! Belagerung beendet.", sourceObjective = "Findet eine Bilgewässer Sprengkapsel bei einem Bilgewässer Pionier und platziert sie bei einem Verwüster der Herrschaftsfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[32153] = { id = 32153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenmörder", description = "Also, Ihr seid zäh. Zäher als die anderen Männer und Frauen hier. Das bedeutet, dass ich Euch für eine Sondermission brauche.\n\nDie Horde setzt ihre Besten gegen uns ein. Die Helden ihrer Armee – Klingenmeister, Taurenhäuptlinge, alles Mögliche.\n\nIch will, dass Ihr einen von ihnen außer Gefecht setzt. Das wird ein schwerer Schlag sein, und zwar nicht nur für ihre Angriffsstärke sondern auch für ihre Moral.", sourceObjective = "Tötet einen Helden der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32154] = { id = 32154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebrannt!", description = "Die Goblins nehmen überhand! Zuerst machen sie den Wald dem Erdboden gleich und stellen diesen scheußlichen Bohrturm auf. Dann werfen sie ihre Ölfässer in die Bucht!\n\nWir müssen diesem Wahnsinn ein Ende setzen! Allerwenigstens müssen wir ihnen eine Schlappe verpassen.\n\nWir müssen ihren Treibstoffvorrat vernichten! Vielleicht gehen dabei auch noch ein paar Goblins mit drauf!", sourceObjective = "Verwendet den instabilen Sprengstoff, um den nordöstlichen Treibstoffbehälter, den nördlichen Treibstoffbehälter und den nordwestlichen Treibstoffbehälter zu zerstören.", completion = "Ich wäre zu gern dort gewesen und hätte dabei zugesehen, wie ihr Treibstoff in Flammen aufgeht! War vermutlich ein ziemlicher Anblick.\n\nDas habt Ihr gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32156] = { id = 32156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gehört sich so", description = "Das ist ein barbarischer Krieg, {class}! Wir haben so viele verloren, die versucht haben, zu verhindern, dass sich der Bilgewasser-Betrieb weiter ausbreitet.\n\nDiese gefallenen Soldaten kämpften ehrenhaft und verdienten es, ihre Sterbesakramente zu bekommen. Zumindest müssen wir in der Lage sein, ihre nächsten Verwandten zu benachrichtigen.\n\nVielleicht könnt Ihr ja ihre Erkennungsmarken einsammeln, damit wir ihnen zumindest in einem kleinen Rahmen Ehre erweisen können.", sourceObjective = "Bergt 7 Erkennungsmarken von den gefallenen Soldaten der Operation Schildwall am Bilgewasserstrand.", progress = "Selbst im Krieg sollte es ein gewisses Maß an Anstand geben.", completion = "Ihr habt diesen Soldaten einen großen Dienst erwiesen, {name}. Jetzt müssen wir nur noch dafür sorgen, dass sie nicht umsonst ihr Leben gelassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32157] = { id = 32157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...ist ein guter Goblin.", description = "Die Zerstörung in Krasarang ist unverzeihlich, {class}. Die einzige Methode, ihr ein Ende zu bereiten, besteht darin, die Bilgewasser-Operation gewaltsam zu stoppen.\n\nDies ist zum übergeordneten Wohl von Pandaria und der Allianz. Geht zum Bilgewasserstrand, und macht sie dem Erdboden gleich! Die Horde wird ihnen zweifelsohne Hilfe leisten.\n\nVernichtet sie!", sourceObjective = "Tötet 10 Bilgewässer Goblins beim Bilgewasserstrand.", completion = "Ausgezeichnet, {class}! Irgendwann werden wir die Horde vollständig von diesem Kontinent vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32158] = { id = 32158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Programm in zwei Schritten", description = "Schreddermeister Packle ist zum Großteil für die Verwüstungen hier unten verantwortlich, {class}.\n\nEs wird gemunkelt, dass er die Schredder umgebaut hat, damit sie schneller arbeiten, ohne Rücksicht auf den Schaden, den sie dadurch verursachen können.\n\nStellt Euch vor, wie schlimm es für die Bäume war, so zugesetzt zu bekommen. Sich von solch einem Ausmaß der Zerstörung wieder zu erholen, wird sehr schwierig sein.\n\nDer erste Schritt besteht darin, anzuerkennen, dass ein Problem besteht. Der zweite Schritt besteht darin, das Problem zu beseitigen.", sourceObjective = "Zerstört Schreddermeister Packle in Blitzbeils Holzhof.", completion = "Gut gemacht, {name}! Nun kann der Wald sich wieder erholen. Aus dem Tod kommt stets neues Leben und eine neue Gelegenheit, es zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32161] = { id = 32161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd des Bestienmeisters: Der Kranich", description = "Gemeinsam mit der Schlinge erhaltet Ihr Ratschläge zur Kranichjagd:\n\nDie größten Kraniche der Krasarangwildnis lassen sich nicht mit simplen Dingen wie Futter ködern. Ihr müsst an die Gefühle der Geschöpfe appellieren, wenn Ihr sie aus ihren Verstecken im Dschungel hervorlocken wollt.\n\nSowohl in Chi-Jis Wiege als auch bei den Narsongtürmen östlich von hier wimmelt es nur so von Kranichen. Rupft ihnen die Federn aus und platziert sie gut sichtbar am Kranichtempel. Eure Beute wird Euch zulaufen.", sourceObjective = "Besorgt 5 makellose goldene Kronenfedern und 1 makellose schwarze Kronenfeder.", progress = "Das ist der Ort, in der Nähe des Kranichtempel.", completion = "Ihr steckt die Federn in den Boden und blickt dann in Richtung Tempel...", sourceObjectiveStatus = "unverified-source-field" }
quests[32162] = { id = 32162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd des Bestienmeisters: Der Tiger", description = "Gemeinsam mit der Falle erhaltet Ihr Ratschläge zur Tigerjagd:\n\nTiger sind gefräßige Kreaturen, und in diesem Dschungel ist Großwild selten. Wenn Ihr die ältesten Katzen aus ihren Verstecken hervorlocken wollt, könnt Ihr das mit einer Mahlzeit versuchen.\n\nAuf der anderen Seite des Schlangenrückens findet Ihr eine Yakherde. Erlegt sie, bringt ihr Fleisch an den Rand des Dschungels, stellt Eure Falle auf und wartet.", sourceObjective = "Besorgt 25 unbeschädigte Yakkeulen.", progress = "Das scheint mir ein idealer Ort für eine Tigerfalle zu sein.", completion = "Ihr legt das Fleisch oben auf die Falle und wendet den Blick dann in Richtung Dschungel...", sourceObjectiveStatus = "unverified-source-field" }
quests[32163] = { id = 32163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd des Bestienmeisters: Die Krabbe", description = "Gemeinsam mit der Kiste erhaltet Ihr Ratschläge zur Krabbenjagd:\n\nKrabben sind merkwürdige Urwesen mit völlig anderen Beweggründen als Ihr und ich.\n\nKleine Krabben sind leicht zu finden und zu fangen, die großen verbergen sich aber unter dem Sand, abseits der Gefahren und unerreichbar. Um sie hervorzulocken, machen wir uns ihren Geruchssinn zunutze.\n\nDie Ungadorfbewohner im Südosten lassen den Fisch, den sie fangen, vor dem Verzehr fermentieren. Sammelt genügend verrotteten Fisch und Ihr werdet eine kolossale Krabbe fangen.", sourceObjective = "Besorgt 30 müffelnde verrottete Fische von Ungadorfbewohnern in Unga Ingu.", progress = "Das sieht nach einem geeigneten Ort aus, um eine Krabbe zu fangen.", completion = "Ihr verteilt den verrottenden Fisch, bereitet die Kiste vor und blickt dann in Richtung Strand...", sourceObjectiveStatus = "unverified-source-field" }
quests[32164] = { id = 32164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd des Bestienmeisters: Der Kranich", description = "Gemeinsam mit der Schlinge erhaltet Ihr Ratschläge zur Kranichjagd:\n\nDen größten Kranichen der Krasarangwildnis sind simple Dinge wie Futter egal. Ihr müsst an die Gefühle der Geschöpfe appellieren, wenn Ihr sie aus dem Dschungel hervorlocken wollt.\n\nSowohl in Chi-Jis Wiege als auch bei den Narsongtürmen westlich von hier sind Kraniche sehr zahlreich. Rupft einigen von ihnen die Federn aus und platziert sie gut sichtbar am Kranichtempel. Eure Beute wird Euch zulaufen.", sourceObjective = "Besorgt 5 makellose goldene Kronenfedern und 1 makellose schwarze Kronenfeder.", progress = "Das ist der Ort, in der Nähe des Kranichtempel.", completion = "Ihr steckt die Federn in den Boden und blickt dann in Richtung Tempel...", sourceObjectiveStatus = "unverified-source-field" }
quests[32165] = { id = 32165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd des Bestienmeisters: Der Tiger", description = "Gemeinsam mit der Falle erhaltet Ihr Ratschläge zur Tigerjagd:\n\nTiger sind Vielfraße, und in diesem Dschungel ist Großwild selten. Wenn Ihr vorhabt, die ältesten Katzen aus ihren Verstecken hervorzulocken, braucht Ihr eine verlockende Mahlzeit.\n\nAuf der anderen Seite des Schlangenrückens befindet sich eine Yakherde. Tötet sie, bringt ihr Fleisch an den Rand des Dschungels, stellt Eure Falle auf und wartet.", sourceObjective = "Besorgt 25 unbeschädigte Yakkeulen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32166] = { id = 32166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd des Bestienmeisters: Die Krabbe", description = "Gemeinsam mit der Kiste erhaltet Ihr Ratschläge zur Krabbenjagd:\n\nKrabben sind merkwürdige alte Geschöpfe mit völlig anderen Beweggründen als wir.\n\nKleine Krabben sind leicht zu finden und zu fangen, die größeren Exemplare verbergen sich aber unter dem Sand, abseits von Gefahren und unerreichbar. Um sie hervorzulocken, machen wir uns ihren Geruchssinn zunutze.\n\nDie Ungadorfbewohner im Südwesten lassen den Fisch, den sie fangen, vor dem Verzehr fermentieren. Sammelt genügend verrotteten Fisch und Ihr werdet eine kolossale Krabbe fangen.", sourceObjective = "Besorgt 30 müffelnde verrottete Fische von Ungadorfbewohnern in Unga Ingu.", progress = "Das sieht nach einem geeigneten Ort aus, um eine Krabbe zu fangen.", completion = "Ihr verteilt den verrottenden Fisch, bereitet die Kiste vor und blickt dann in Richtung Strand...", sourceObjectiveStatus = "unverified-source-field" }
quests[32167] = { id = 32167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Uralten", description = "Der Kranich ist gefallen.Ihr erlernt:", sourceObjective = "Sprecht mit Jorn Himmelsdeuter an der Herrschaftsfeste in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
