quests[32175] = { id = 32175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampf des Dunkelmonds!", description = "Seid Ihr bereit, den Mut Eurer Haustiere auf die Probe zu stellen...?", sourceObjective = "Besiegt Jeremy Feasel in einem Haustierkampf.", completion = "Ich muss schon sagen – tolle Show.", sourceObjectiveStatus = "unverified-source-field" }
quests[32181] = { id = 32181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Kranich", description = "Der uralte Kranich lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jorn Himmelsdeuter bringen, bevor er aufwacht.", sourceObjective = "Bringt den uralten Blutkronenkranich zu Jorn Himmelsdeuter.", progress = "Willkommen zurück, {name}.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Anmut des Kranichs an der Macht der Horde testen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32182] = { id = 32182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Tiger", description = "Der Katzen-Älteste lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jorn Himmelsdeuter bringen, bevor er aufwacht.", sourceObjective = "Bringt den Krasariältesten zu Jorn Himmelsdeuter.", progress = "Willkommen zurück, {name}.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Wildheit des Tigers an der Macht der Horde testen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32183] = { id = 32183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Die Krabbe", description = "Die kolossale Krabbe lebt, ist aber betäubt.\n\nIhr solltet sie zu Jorn Himmelsdeuter bringen, bevor sie aufwacht.", sourceObjective = "Bringt die kolossale Zwingzange zu Jorn Himmelsdeuter.", progress = "Willkommen zurück, {name}.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Widerstandsfähigkeit der Krabbe an der Macht der Horde testen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32184] = { id = 32184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Kranich", description = "Der uralte Kranich lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jäger Blake bringen, bevor er aufwacht.", sourceObjective = "Bringt den uralten Blutkronenkranich zu Jäger Blake.", progress = "Willkommen zurück, {name}.", completion = "Zum Ergreifen der Bestie war zwar nur ein {race} erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Anmut des Kranichs gegen den Ruhm der Allianz antreten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32185] = { id = 32185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Tiger", description = "Der Katzen-Älteste lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jäger Blake bringen, bevor er aufwacht.", sourceObjective = "Bringt den Krasariältesten zu Jäger Blake.", sourceObjectiveStatus = "unverified-source-field" }
quests[32186] = { id = 32186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Die Krabbe", description = "Die kolossale Krabbe lebt, ist aber betäubt.\n\nIhr solltet sie zu Jäger Blake bringen, bevor sie aufwacht.", sourceObjective = "Bringt die kolossale Zwingzange zu Jäger Blake.", progress = "Willkommen zurück, {name}.", completion = "Zum Ergreifen der Bestie war zwar nur ein {race} erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Ausdauer der Krabbe gegen den Ruhm der Allianz antreten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32190] = { id = 32190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Mogujia", description = "Throm-ka, {class}. Während wir damit beschäftigt waren, unsere Stellung hier zu verteidigen, hat Lordregent Lor'themar Theron eine Forschungsexpedition zum Kun-Lai-Gipfel im Norden geführt.\n\nLeider sieht es so aus, als wäre sie in Schwierigkeiten geraten.\n\nKriegshäuptling Garrosh Höllschrei ist bereits zu Hilfe geeilt, wir brauchen aber weitere Verstärkung.\n\nBrecht nach Norden zum Kun-Lai-Gipfel auf. Sprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.", sourceObjective = "Findet Lordregent Lor'themar Theron bei Mogujia. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32191] = { id = 32191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Wächter", description = "Ehe die Mogu unseren Spähtrupp überwältigten, haben wir Relikte gefunden, die in den Ruinen im Norden verstreut waren.\n\nIch würde gern ein paar Proben davon einsammeln, mit den Terrakotta-Wachhunden der Mogu werden wir aber nicht fertig.\n\nWenn Ihr die Umgebung von ihnen säubern könntet, werden wir unsere Arbeit fortsetzen.", sourceObjective = "Tötet 5 Wächter der Korun.", sourceObjectiveStatus = "unverified-source-field" }
quests[32192] = { id = 32192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutlinie", description = "Wir konnten die Wächter der Mogu und ihre Hunde zurückschlagen, etliche Blutelfen aus dem Spähtrupp hatten allerdings nicht so viel Glück.\n\nViele von meinen Leuten sitzen in den Ruinen im Norden fest. Wir arbeiten an einer Lösung, um sie herauszuholen, ich glaube aber, dass es eine unkompliziertere Vorgehensweise gibt.\n\nBegebt Euch zu den Ruinen und tötet alle Wächter, die einen Gefangenen bewachen. Wenn meine Eingebung mich nicht trügt, können wir so unsere Kameraden befreien.", sourceObjective = "Befreit 6 Magier der Herrschaftsoffensive indem Ihr Hüter der Korun tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32193] = { id = 32193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Mogujia", description = "Die Forscherliga hat vor ein paar Tagen eine Expedition nach Norden entsandt.\n\nSeither haben wir nicht mehr von ihr gehört und ich würde nachts besser schlafen, wenn ich wüsste, dass unsere Leute nicht in Schwierigkeiten stecken.\n\nMeinen letzten Informationen zufolge war Brann Bronzebart nach Mogujia am Kun-Lai-Gipfel unterwegs.\n\nFindet ihn und erstattet Bericht über ihre Lage. Fennie dort drüben kann Euch hinbringen.", sourceObjective = "Sprecht mit Brann Bronzebart in Mogujia am Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung für einen Transport.", sourceObjectiveStatus = "unverified-source-field" }
quests[32194] = { id = 32194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böses Blut", description = "Die Forscherliga ist hier, um die Ruinen auszugraben und meine Aufgabe ist es, sie zu beschützen.\n\nAls wir hier ankamen, wimmelte es nur so von Blutelfen. Die Horde scheint genauso großes Interesse an den Mogu zu haben wie wir.\n\nDas ist eine gute Gelegenheit für uns, einige von ihnen aus dem Weg zu schaffen und gleichzeitig ihre Ergebnisse zu stehlen.\n\nTötet die Blutelfen, die Ihr in den Ruinen antrefft, und nehmt ihnen ab, was sie ausgegraben haben.", sourceObjective = "Erlangt 5 Artefakte der Korun von Runensuchern von Silbermond oder von Magiern oder Rittern der Herrschaftsoffensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[32195] = { id = 32195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgestauter Zorn", description = "Wie es aussieht, wimmelt es hier nur so von verbleibender Sha-Energie.\n\nIhr wisst, was Ihr zu tun habt, {name}. Vernichtet auch die letzten Überbleibsel.", sourceObjective = "Tötet 27 Zornlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[32197] = { id = 32197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenartiger Braten", description = "Wir kriegen von überall her Beschwerden, dass die Chefin das ganze gute Essen bekommt und den anderen nur die Reste überlässt.\n\nGanz unter uns, da kann etwas dran sein. Selbst ich bekomme kein so gutes Essen wie sie!\n\nWir brauchen etwas, von dem Sezik eine Menge machen kann, um wenigstens darüber hinwegzutäuschen, wie ungenießbar das Essen hier ist...\n\nIch hab's! Eigenartiger Braten!", sourceObjective = "Besorgt 7 Stücke eigenartiges Fleisch von den wilden Tieren aus der Gegend.", progress = "Was habt Ihr für mich?", completion = "Ich habe Maßstäbe, müsst Ihr wissen! Ich bin Koch, kein Zauberkünstler!\n\nDas richtig Eigenartige hier ist, wie Duke das schaffen will, alle reinzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32210] = { id = 32210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moguboss für Schlüssel töten, Objekt hinter Sprungpuzzle benutzen" }
quests[32221] = { id = 32221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstürmung des Strandes", description = "Unsere Holzvorräte sind durch ständige Angriffe aus der Löwenlandung gefährdet.\n\nBisher konnten wir die Angreifer in Schach halten, es wird aber Zeit, dass wir die Muskeln spielen lassen!\n\nBrecht zur Küste auf und spaltet ein paar Schädel!", sourceObjective = "Tötet 10 beliebige Angreifer der 7. Legion.", progress = "Ist der Holzhof sicher?", completion = "Ausgezeichnete Arbeit dort unten, {name}! Das sollte sie uns eine Zeit lang vom Leib halten!", sourceObjectiveStatus = "unverified-source-field" }
quests[32223] = { id = 32223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Leutnant Ethan Jacobson", description = "Wegen Verbrechen an den Truppen der Herrschaftsfeste gesucht!\n\nLeutnant Ethan Jacobson ist für die Ausführung mehrerer Bodenangriffe gegen den Holzbetrieb von Bilgewasser verantwortlich.\n\nEr wurde zuletzt auf einer Insel im Süden von Blitzbeils Holzhof gesichtet.", sourceObjective = "Tötet Leutnant Ethan Jacobson auf den Südlichen Inseln im Süden von Blitzbeils Holzhof.", completion = "Jeder Tag, an dem ein weiterer Anführer der Löwenlandung fällt, ist ein guter Tag, {class}! Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[32229] = { id = 32229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodierenden Trollkampftrupp töten" }
quests[32235] = { id = 32235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosiver Cocktail!", description = "Die Gnome haben ihre Fluggeräte mitgebracht. Ich will, dass mein Himmel FREI bleibt!\n\nEgal, welches Reittier Ihr bei Euch habt – hinauf mit Euch und zerstört diese erbärmlichen Geräte.\n\nIhr könnt diesen Grog verwenden, den ich von einem unserer Goblinverbündeten \"besorgt\" habe. Ihr wärt besser damit bedient, mit ihm Gyrokopter aus der Luft zu holen, als ihn in den Gurgeln dieser kleinen grünen Unholde versickern zu lassen.", sourceObjective = "Verwendet den Bilgewässer Molotowcocktail, um 6 Gyrokopter X2 der Himmelsfeuer zu zerstören.", completion = "Ha! Primitive mechanische Spielzeuge können es mit einer gezielt geworfenen Flasche Grog nicht aufnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32236] = { id = 32236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kratz-Ab!", description = "In dieser Höhle wimmelt's nur so vor fiesen Schieferspinnen! Wie soll man denn seine Arbeit erledigen, wenn sie die Minenarbeiter UND das Erz auffressen?!\n\nDas wäre eine gute Gelegenheit, meine neue Erfindung einzusetzen: Kratz-Ab! Man muss einfach nur die Schieferspinnen mit diesem Zeug einsprühen. Das mögen die gar nicht, und für die Minenarbeiter scheint es kaum längerfristige Nebenwirkungen zu haben!\n\nWas kann da schon schiefgehen?\n\nNehmt diesen praktischen Sprüher mit und macht Euch an die Arbeit.", sourceObjective = "Sprüht 5 Aufgebrachte Schieferspinnen mit dem \"Kratz-Ab\"-Spray ein und beseitigt 12 Schiefersplitter.", progress = "Schieferspinnen. Ich hasse Schieferspinnen.", completion = "Na das hört man gerne! Ich wette, diese Spinnen werden es sich jetzt zweimal überlegen, bevor sie sich wieder in eine Bilgewasseroperation einmischen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32238] = { id = 32238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Universalfernsteuerungsexplosion", description = "Die Mecha-Stampfer machen uns hier wirklich das Leben schwer, doch ich glaube, ich habe die Lösung!\n\nIch habe mir diese Universalfernsteuerung gebaut, aber scheinbar arbeitet sie auf einer bestimmten Frequenz, die eine nützliche Wirkung hat!\n\nEs scheint ganz so, als schwäche diese Frequenz ihre Rüstung!\n\nBenutzt die Fernsteuerung, um sie von ihrem hohen Ross zu holen und ihnen dann die Visage zu polieren!", sourceObjective = "Zerstört 9 Mecha-Stampfer des Schildwalls in und um Blitzbeils Holzhof.", sourceObjectiveStatus = "unverified-source-field" }
quests[32242] = { id = 32242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Geheimnisse", description = "Ich habe gehört, dass die Mogu einst Hunderte verborgener Waffenkammern voller erderschütternder Waffen ihr Eigen nannten.\n\nWenn sich eine Moguarmee für den Krieg rüstete, erfüllte sie die Herzen ihrer Feinde mit Furcht und Schrecken.\n\nDas ist GENAU die Art Wissen, die ich hier in Pandaria suche!\n\nIch habe eine Expedition entsandt, um ein paar Ruinen im Westen zu erforschen, aber ihre Arbeitsmoral ist die schwachsinniger Peons!\n\nGeht hin und sprecht mit Fanlyr Silberdorn, ihrem Anführer. Sagt ihm, dass ich Resultate sehen will, und zwar sofort.", sourceObjective = "Sprecht mit Fanlyr Silberdorn bei der Ahnenhöhe im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32243] = { id = 32243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Machtquelle der Korun", description = "Nah halli-hallo! Habt Ihr schon mal so was geseh'n wie die alten Statuen hier? Faszinierend!\n\nAls ich vorhin die Ruinen da oben ausgekundschaftet hab', ist mir auf dem höchsten Punkt oben was Interessantes aufgefall'n.\n\nIch kam nicht nah genug ran, aber ich glaub', es könnte eine von diesen Mogustatuen sein... außer, dass sie sich bewegt hat!\n\nIch schaff's nicht durch diese ganzen fiesen Blutelf'n, aber Ihr seht aus, als hättet Ihr das Zeug dazu.\n\nWürd' es Euch was ausmachen, da hochzuklettern und mir zu bringen, was immer von Interesse sein könnte?", sourceObjective = "Nehmt dem Spruchwirker der Korun eine Sha-berührte Klaue ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32244] = { id = 32244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Korun", description = "Diese Terrakottawächter sind beängstigend, aber nicht annähernd so furchterregend wie die Geschöpfe, die uns ganz oben in den Ruinen begegnet sind.\n\nEinige Überlebende unter unseren Spähern wollen eine Art Spruchwirker der Mogu auf der höchsten Erhebung im Norden gesehen haben.\n\nEr praktiziert eine Magie, wie wir sie noch nie erlebt haben.\n\nWir müssen möglichst viel über diese Kreatur erfahren. Tötet ihn und bringt mir alles, was Ihr findet.", sourceObjective = "Nehmt dem Spruchwirker der Korun einen Korunkodex ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32246] = { id = 32246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit der Späherin", description = "Es ist zwei Monate her, seitdem sich die Nebel gelichtet haben. Späher der Allianz, die nach einem geeigneten Ankerplatz für ihre Flotte suchen, haben die Streitmächte der Horde an einem Strand in der Krasarangwildnis in ein Gefecht verwickelt.\n\nTrefft Euch mit Späherin Lynna, um bei der Eroberung des Landeplatzes zu helfen.", sourceObjective = "Sprecht mit Späherin Lynna in der Krasarangbucht in der Krasarangwildnis.", completion = "Ihr kommt gerade rechtzeitig, {class}. König Wrynn wird gleich hier sein, und die volle Kampfkraft unserer Flotte wird schon bald folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32247] = { id = 32247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein König unter den Menschen", description = "Es ist höchste Zeit, wir müssen Trottmann finden und den Strand sichern.\n\nAußerdem sollten wir nach den Zwergen sehen - die Forscherliga ist zäh, ihre Mitglieder sind aber keine Soldaten. Sie sollten sich an der Klippe nördlich von hier aufhalten.\n\nReiten wir los, {class}. Für unsere Freunde. Für die Allianz.", sourceObjective = "Tötet 25 Mitglieder der Horde und begleitet König Varian Wrynn, um Marschall Trottmann und Hilda Hornsturz zu finden.", progress = "Die Allianz wird der Schild sein, der Pandaria vor der Horde schützt.", completion = "Ich bin zufrieden mit dieser Stelle. Zeit, die Flotte an Land kommen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32248] = { id = 32248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Geduld", description = "König Varian braucht entschlusskräftige Abenteurer, um ihm beim Entscheidungskampf zwischen Tyrande Wisperwind und einer Einheit Hordenkrieger, die sich im Tempel des Roten Kranichs verschanzt haben, zu helfen.\n\nMeldet Euch unverzüglich bei ihm!", sourceObjective = "Betretet das Szenario Ein wenig Geduld und meldet Euch bei König Varian Wrynn.", completion = "Schön, Euch wiederzusehen, {name}.\n\nWir haben es hier mit einer heiklen Situation zu tun. Wir müssen unsere nächsten Schritte vorsichtig planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32249] = { id = 32249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit der Späherin", description = "Es ist zwei Monate her, seitdem sich die Nebel gelichtet haben. Späher der Horde, die nach einem geeigneten Ankerplatz für ihre Flotte suchen, haben die Streitmächte der Allianz auf einer kleinen Insel vor der Küste der Krasarangwildnis in ein Gefecht verwickelt.\n\nTrefft Euch mit Späherin Rokla, um bei der Eroberung des Landeplatzes zu helfen.", sourceObjective = "Sprecht mit Späherin Rokla bei der Landezone der Horde in der Krasarangwildnis.", completion = "Ihr kommt gerade rechtzeitig. Der Kriegshäupling wird gleich eintreffen. Wenn dieser Ort seiner Inspektion standhält, wird die Flotte folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32250] = { id = 32250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Kriegshäuptlings", description = "Kommt, {class}! Ich möchte diese Insel erkunden und sicherstellen, dass mein Landungstrupp seine Arbeit gemacht hat.\n\nBlutwache Gro'tash sollte irgendwo auf der Nordseite der Insel nach einem geeigneten Ort zur Errichtung unserer Festung suchen. Das Untersuchungsteam der Goblins wird auf der Suche nach Öl zur Ostküste gegangen sein.\n\nMachen wir diesem lächerlichen Schauspiel ein Ende - dieses Land soll der Horde gehören!", sourceObjective = "Begleitet Garrosh Höllschrei, sucht Blutwache Gro'tash und Grizzle Radflutsch und tötet 25 Mitglieder der Allianz.", progress = "Blutschrei dürstet nach dem Blut der Allianz.", completion = "Gute Arbeit. Niemand kann unsere Präsenz hier verhindern!", sourceObjectiveStatus = "unverified-source-field" }
quests[32251] = { id = 32251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dolch im Dunkel", description = "Schattenjäger Vol'jin hat sich einer Spähergruppe der Kor'kron bei einer wichtigen Mission für den Kriegshäuptling angeschlossen.\n\nEin stolzes Mitglied der Horde wie Ihr kann natürlich gern mitkommen, seid aber gewarnt - es könnte unangenehm werden.", sourceObjective = "Betretet das Szenario Ein Dolch im Dunkel und meldet Euch bei Vol'jin.", completion = "Schön, dich zu seh'n, Mann. Für diese Mission brauch ich echte Verbündete an meiner Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[32256] = { id = 32256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg eines Reichs", description = "Kriegshäuptling Garrosh Höllschrei ist mit einem Trupp seiner besten Elitesoldaten gen Norden ausgeschwärmt.\n\nErstattet ihm von unserer Siegesserie im Kampf gegen die Allianz Bericht.\n\nSprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.", sourceObjective = "Findet Kriegshäuptling Höllschrei beim Schrein der Zwei Monde. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32257] = { id = 32257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimme der Götter", description = "Zu langsam!? Wir arbeiten für den Kriegshäuptling, so schnell wir nur können!\n\nWir müssen vorsichtig bei den Ausgrabungen vorgehen, jeden Fund einzeln katalogisieren und natürlich auch die Sicherheitsvorschriften befolgen. Das muss er schon verstehen!\n\nNun, möglicherweise haben wir ihm schon bald etwas zu zeigen. Seht Ihr diese Steinstatue im Westen?\n\nWir vermuten, dass es sich bei ihr um ein antikes Steinspeicherbehältnis handelt. Jetzt müssen wir nur noch einen Weg finden, es zu öffnen.\n\nWenn Ihr uns bei unseren Ausgrabungen helfen möchtet, geht bitte vorsichtig vor.", sourceObjective = "Untersucht den Quecksilberwächter und besorgt die uralte Tafel der Korun.", sourceObjectiveStatus = "unverified-source-field" }
quests[32284] = { id = 32284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand, den Ihr treffen solltet", sourceObjective = "Findet Chen Sturmbräu in Binan. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32286] = { id = 32286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsucher der Mogu töten (wandernde Zweirgruppen, die Späher aktiv bekämpfen und Rituale an Leichen durchführen)" }
quests[32318] = { id = 32318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regeneration will Weile haben", description = "Vol'jin wäre tot, wenn er kein Troll wäre. Seine Regenerationsfähigkeit ist beeindruckend, aber sie wird durch ein Gift behindert.\n\nWir müssen dieses Gift eliminieren, damit er den Schaden regenerieren kann.\n\nErhebt Euch in die Lüfte und brecht gen Südosten auf. Auf den Gipfeln des Versteckten Horsts werdet Ihr Nadelgeister antreffen. Bringt mir die härtesten ihrer Nadeln, die Ihr finden könnt.\n\nMit ihnen kann ich eine Akupunkturtechnik versuchen, die seinen Körper von dem Gift reinigen und seine Regeneration beschleunigen sollte.", sourceObjective = "Sammelt 10 starke Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32319] = { id = 32319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Thrall!", description = "<Vol'jin öffnet halb ein Auge und bewegt die Lippen, als setze er zu sprechen an. Obwohl er keinen Ton herausbringt, versteht Ihr zwei Worte.>\n\nSucht Thrall.\n\n<Mit Anstrengung drückt Vol'jin Euch einen Ruhestein in die Hände, bevor er ohnmächtig wird.>", sourceObjective = "Spürt Thrall mithilfe von Vol'jins Ruhestein auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32320] = { id = 32320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde ist wie eine Familie", sourceObjective = "Eskortiert Thrall zu den Echoinseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32331] = { id = 32331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kirin Tor", sourceObjective = "Tretet durch das Portal zum Purpursalon in der Löwenlandung und trefft Euch mit Anduin Wrynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[32342] = { id = 32342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geisterfalle", description = "Wir haben mehrere mächtige Artefakte der Mogu in den Ruinen identifizieren können. In ihnen haben sie Geister eingefangen, die sie vermutlich bei einem Ritual oder einer Beschwörung einzusetzen beabsichtigten.\n\nEs handelt sich hier um ein Gerät, das wir bislang nicht identifizieren konnten und dringend erforschen müssen – die Artefakte könnten uns weiteren Aufschluss über die Geistbindungstechniken der Mogu geben. \n\nGeht und sucht ein paar Proben für uns, damit wir sie richtig untersuchen können.", sourceObjective = "Sammelt 3 Geisterfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32343] = { id = 32343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogudeis Leutnants", description = "Es gibt zwei extrem mächtige Mogugeister, welche die Allianz in ihrem Dilettantismus entfesselt hat.\n\nSie sind die idealen Ziele für uns, {class}. Wenn Ihr sie tötet und die Essenzen beider an Euch nehmt, könnte dies einen großen Fortschritt bei der Entschlüsselung der Geschichte dieser sonderbaren Ruine bedeuten.", sourceObjective = "Sammelt Meng-dos Essenz und Gen-lis Essenz in den Ruinen von Ogudei.", sourceObjectiveStatus = "unverified-source-field" }
quests[32345] = { id = 32345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind keine Monster!", description = "Die Archäologische Akademie mag in der Vergangenheit einen schlechten Ruf gehabt haben, aber wir sind keine Monster. Wir vertreten lediglich andere Ansichten über die Archäologie als die Forscherliga.\n\nAb und zu widmen wir uns ganz der Vollbringung von Heldentaten. Also geht und befreit ein paar der Sklavengeister der Pandaren in den Ruinen.", sourceObjective = "Befreit 14 aufgewühlte Sklavengeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[32346] = { id = 32346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hab' keine Angst vor Gespenstern!", description = "Schaut, wir haben hier ein übles Problem, und der alte Trottmann drüben in der Löwenlandung schmeißt uns glatt raus, wenn wir hier nicht bald alles unter Kontrolle kriegen.\n\nHelft uns doch bitte!", sourceObjective = "Tötet 12 geistgebundene Mogu.", sourceObjectiveStatus = "unverified-source-field" }
quests[32347] = { id = 32347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räumungsklage", description = "Diese verdammte Archäologische Akademie hat sich in die Ruinen geschlichen. Sie haben sich im unteren Bereich festgesetzt und treiben da unten allerhand magischen Schabernack.\n\nZeit, dass wir ihnen 'ne Räumungsklage an den Hals hängen, und zwar in Form eines Stiefels im Hinterteil!", sourceObjective = "Tötet 10 beliebige Anhänger der Archäologischen Akademie in den Ruinen von Ogudei.", sourceObjectiveStatus = "unverified-source-field" }
quests[32348] = { id = 32348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tretet sie, wenn sie am Boden liegen", description = "Dass sie ihre Basis in solcher Nähe eingerichtet hat, legt nahe, dass die Allianz denkt, sie habe die Ruinen fest in ihrem Würgegriff.\n\nDiese Fehleinschätzung werden wir ihr schon noch austreiben. Los, schaltet ein paar ihrer Wachen aus.", sourceObjective = "Tötet 12 Militäreinheiten der Löwenlandung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32351] = { id = 32351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo des Donners", description = "Ah, {name}, so sieht man sich wieder. Ich habe erstaunliche Nachrichten.\n\nOberhäuptling Baine Bluthuf der Tauren ist in Pandaria eingetroffen.\n\nEr ist zu einem Treffen mit Kriegshäuptling Garrosh Höllschrei und dem Lordregenten Lor'themar Theron am Schrein der Zwei Monde im Tal der Ewigen Blüten unterwegs.\n\nEr sandte mir eine seltsame Bitte – ich soll ihm einen treuen Verfechter der Horde schicken, der des Kampfes fähig ist... und der Diskretion.\n\nIch kann mir niemand Besseren als Euch dafür vorstellen. Sprecht mit Tak-Tak, wenn Ihr eine Transportmöglichkeit sucht.", sourceObjective = "Findet Oberhäuptling Baine Bluthuf beim Schrein der Zwei Monde. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32352] = { id = 32352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sturm zieht auf", description = "Wenn General Nazgrim Euch schickt, vertraue ich auf Eure Diskretion.\n\nAls ich hier ankam... experimentierte... Garrosh mit uralter Macht, die er in den Bergen im Norden gefunden hatte.\n\nEr glaubt, dass dieses \"Sha\" unsere Soldaten stärken kann.\n\nLeider legen die Resultate bislang die gegenteilige Wirkung nahe.\n\nUnsere Truppen scheinen ohne Sinn und Verstand gewalttätig zu werden. Geht und verhört sie. Verteidigt Euch, falls sie Euch bedrohen.", sourceObjective = "Nehmt es mit 6 Sha-berührten Grunzern auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32362] = { id = 32362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalarans Schicksal", description = "Jaina weigert sich, mir zuzuhören. Vater hatte gehofft, ich könnte sie irgendwie beeinflussen, ich glaube jedoch, sie sieht mich immer noch als Kind.\n\nIhr seid aber <ein Held/eine Heldin> der Allianz und ich weiß, dass sie respektiert, was Ihr tut.\n\nGibt es etwas, das Ihr sagen könntet, um sie davon zu überzeugen, dass wir ihre Hilfe brauchen?", sourceObjective = "Sprecht mit Jaina Prachtmeer und hört Euch ihre Geschichte an.", sourceObjectiveStatus = "unverified-source-field" }
quests[32369] = { id = 32369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Vergangenheit" }
quests[32372] = { id = 32372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Unterwerfung", description = "Die Kor'kron sind die besten und treuesten Soldaten des Kriegshäuptlings. Ihre Anwesenheit hier bedeutet, dass Garrosh einen Aufstand befürchtet.\n\nVol'jin und sein Volk sind genauso Teil der Horde wie jeder Orc.\n\nWir müssen die Belagerung beenden und die Trolle befreien. Es schmerzt mich, dies zu sagen, aber Ihr müsst so viele der Kor'kron töten, dass die Trolle ihre Stadt zurückerobern können. Danach trefft mich in der Dunkelspeerfeste und wir fordern ihren Offizier direkt heraus.", sourceObjective = "Tötet 10 Aufseher der Kor'kron, 5 Unterwerfer der Kor'kron und Gul'tar den Unterwerfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[32373] = { id = 32373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was den Anführer ausmacht", description = "Die Pandarenkampagne ist inzwischen fortgeschritten. Die Allianz ist mit der versammelten Macht Ihrer Marine an der Küste gelandet. Euer König möchte der Hordeaggression in diesem neuen Land Einhalt gebieten.\n\nGarrosh Höllschrei treibt die Horde geradeheraus in den Kampf, aber König Varian Wrynn kann ich nicht so leicht durchschauen. Habt Ihr einen Augenblick Zeit? Ich würde gern über diesen Anführer von Euch sprechen.", sourceObjective = "Sprecht mit Furorion in der Taverne im Nebel.", completion = "Ich bin gespannt darauf, zu sehen, wie König Wrynn auf die Situation reagiert.\n\nNoch neugieriger bin ich allerdings darauf, zu erfahren, wozu IHR in der Lage seid. Lasst es uns herausfinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[32374] = { id = 32374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzliches Anliegen", description = "Mein Ziel ist das schnelle Ende dieses kostspieligen Krieges. Beweist mir, dass die Allianz es verdient, zu gewinnen. Zeigt mir Euer Können auf dem Schlachtfeld.\n\nIhr werdet nicht gegen eine abstrakte Macht wie das Sha kämpfen, sondern Euren Gegnern direkt gegenüberstehen.\n\nWerdet Ihr siegen?", sourceObjective = "Tötet Hordetruppen entlang der südlichen Küsten der Krasarangwildnis bis Ihr beim Schwarzen Prinz einen respektvollen Status erreicht.", completion = "Hervorragend! Selbst im Chaos des Kampfes habt Ihr bewiesen, dass jede einzelne Person einen Unterschied machen kann. Die Horde hat lernen müssen, dass ihre Taten in Pandaria auf Widerstand treffen werden.\n\nIch glaube, es ist an der Zeit für eine anspruchsvollere Aufgabe...", sourceObjectiveStatus = "unverified-source-field" }
quests[32376] = { id = 32376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Tal!", description = "Diese versiegelte Nachricht wurde für Euch geschickt, zusammen mit dem dringenden Befehl, ins Tal der Kaiser auf dem Kun-Lai zu reisen.\n\nEs scheint ernst zu sein. Ich an Eurer Stelle würde nicht zögern.\n\nSprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.", sourceObjective = "Findet Euren \"Freund aus Silbermond\" im Tal der Kaiser. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32378] = { id = 32378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg bereiten", description = "Eins nach dem anderen. Wenn wir den Anführer gefangen nehmen wollen, müssen wir die Zahl seiner Agenten verringern.\n\nSeid vorsichtig. Diese Mogu sind besonders gefährlich – es scheint, als ob sie das Sha in einer uns bisher unbekannten Weise beeinflussen können.", sourceObjective = "Tötet 10 Korunmogu.", sourceObjectiveStatus = "unverified-source-field" }
quests[32379] = { id = 32379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe der Korun", description = "Ich bin nicht bereit, noch mehr unseres Volkes im Kampf gegen einen Feind, den wir weder kennen noch verstehen, zu opfern.\n\nSchaut bitte, ob ihr in diesem Gebiet irgendwelche Hinweise findet, die besagen, wer diese \"Korunmogu\" sind. Nur für den Fall, dass der Einsatz nicht wie geplant abläuft.", sourceObjective = "Findet das Dokument 'Das Vermächtnis der Korun' im Tal der Kaiser und besorgt das versiegelte Artefakt der Korun und die Korunbefehle von den Mogu der Korun.", sourceObjectiveStatus = "unverified-source-field" }
quests[32380] = { id = 32380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beste hier", description = "Wir werden Hilfe benötigen, wenn wir herausfinden wollen, was Garrosh mit Pandaria vorhat.\n\nIch denke da an jemand Bestimmten, aber er wird nicht leicht zu überzeugen sein.\n\nAgent Connelly glaubt zwar, er sei im Ruhestand, aber den SI:7 verlässt man nicht einfach so. Schon seit Monaten folgt ihm einer unserer Geheimagenten.\n\nMomentan tarnt er sich als ein Profiglücksspieler in Bizmos Boxbar. Hat irgendetwas mit der Begleichung einer alten Rechnung zu tun.\n\nTrefft Euch mit unserem Geheimagenten in der Kampfgilde.", sourceObjective = "Meldet Euch bei Geheimagentin Townsley in Bizmos Boxbar auf der Sturmwindseite der Tiefenbahn.", sourceObjectiveStatus = "unverified-source-field" }
quests[32381] = { id = 32381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Spion fängt", description = "Nun, ich könnte Euch sagen, wer Connelly ist, aber das wäre zu einfach! Um einen Spion zu erwischen, müsst Ihr wie ein Spion denken.\n\nZunächst müsst Ihr den Test bestehen!\n\nDie kleinsten Dinge können viel über eine Person aussagen. Der Teufel steckt im Detail.\n\nIch werde Euch ein Getränk geben, das Ihr serviert. Ich werde Euch ein kleines Detail darüber verraten, was der Empfänger trägt. Alles andere liegt an Euch.\n\nSeid vorsichtig, wem Ihr etwas zu trinken gebt. Die Leute hier können ziemlich ungehalten werden, wenn Ihr ihnen das falsche Getränk hinstellt!", sourceObjective = "Bringt das rosarote Murmeltier, die Mogumelonenüberraschung und den rostigen Dolch zu den richtigen Gästen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32382] = { id = 32382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekt getarnt", description = "Agent Connelly konnte Garroshs Lager auf dem Kun-Lai-Gipfel infiltrieren und beobachtet alles, was dort vor sich geht! \n\nEr hat spezifisch nach Euch gefragt, um ihm bei der Beschaffung wichtiger Informationen zu helfen.\n\nEr hat eine Tarnung für Euch geschickt. Vergesst nicht, sie anzulegen, bevor Ihr Euch dem Lager nähert! Es wird ganz gewiss schwer bewacht.\n\nEr ist sich sicher, dass Ihr ihn erkennen werdet, wenn Ihr ihn seht. Sagte, Ihr hättet ein scharfes Auge fürs Detail...\n\nSprecht mit Fennie dort drüben und sie bringt Euch hin.", sourceObjective = "Trefft Connelly auf dem Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung bezüglich einer Transportmöglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32383] = { id = 32383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwanzt", description = "Ich habe einige Wanzen im Lager verteilt, aber mehr schaden nie.\n\nIch habe sie so getarnt, dass sie wie Statuen aussehen. Zwischen all den anderen Artefakten fallen sie überhaupt nicht auf.\n\nEure Tarnung sollte es Euch ermöglichen, Euch frei im Lager zu bewegen. Bleibt nur dem Hund fern und haltet Euch nicht in Garroshs Nähe auf! Nero und Garrosh werden Eure Tarnung durchschauen!\n\nIch kann Euch nicht helfen, wenn Ihr erwischt werdet. Ich darf die Mission nicht gefährden!", sourceObjective = "Verwanzt das große Zelt in der Nähe der kleinen Zelte sowie die Vorräte mit clever getarnten Wanzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32384] = { id = 32384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Anführer gefangen nehmen", description = "Gut, es ist an der Zeit, zuzuschlagen. Geht zum Grab der Schatten, schwächt ihn und nehmt ihn gefangen.\n\nIch bleibe hier, falls Garrosh eintrifft. Ich werde versuchen, ihn aufzuhalten, sodass wir unsere Beute an uns nehmen können, bevor er sie zerstört.\n\nBeeilt Euch!", sourceObjective = "Schwächt und ergreift Shan Kien am Grab der Schatten am Kun-Lai-Gipfel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32388] = { id = 32388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führungswechsel", description = "Es gibt einen General der Orcs, den ich schon länger beobachte. Kriegsfürst Blutheft hat sich bei Garrosh Höllschrei eingeschmeichelt, indem er einen Vorstoß der Allianz im Südlichen Brachland zurückgeschlagen hat. Jetzt hat er sich in der Herrschaftsfeste verschanzt.\n\nIch bezweifle, dass die Allianz ihn besiegen kann. Aber... Ihr habt mich schon einmal eines Besseren belehrt.\n\nWenn Ihr ihn ausschalten wollt, bringt Freunde mit. Viele Freunde.", sourceObjective = "Tötet Kriegsfürst Blutheft in der Herrschaftsfeste in der Krasarangwildnis. Ihr werdet eine Gruppe benötigen.", completion = "<Furorion grinst.>\n\nIhr wurdet auf die Probe gestellt, {class}. Ich wusste, dass Ihr allein große Dinge bewerkstelligen könnt.\n\nAber jetzt habt Ihr mir bewiesen, dass Ihr ein wahrer Anführer seid, der inmitten eines Schlachtfelds eine Gruppe von Fremden zu leiten vermag.\n\nDie Allianz kann sich glücklich schätzen, Euch zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32389] = { id = 32389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Löwe brüllt", description = "Dies ist ein weltweiter Krieg, {name}. Er ist bis nach Pandaria gelangt und hat Krisenherde in Kalimdor und den Östlichen Königreichen in Brand gesetzt. Wie verhaltet Ihr Euch in einem organisierten Kampf? Das würde ich gern selbst sehen.\n\nIch erwarte Euren Bericht von der Front.", sourceObjective = "Gewinnt Kämpfe im Tempel von Katmogu und in der Silberbruchmine.", completion = "<Furorions Augen leuchten glühend rot während er gierig den Berichten Eurer Heldentaten auf den Schlachtfeldern lauscht.>\n\nOhh... oh! Unglaublich! Im Schlachtgetümmel zeigt sich das wahre Herz eines Kämpfers.\n\nIhr enttäuscht nicht, {name}.\n\nGenauso wenig wie die Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[32390] = { id = 32390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Rudelführers", description = "{class}, durch Eure Augen konnte ich die Kämpfe entlang der Küste und den epischen Verlauf der Gefechte in der ganzen Welt verfolgen. Ihr wart sehr geduldig... und habt mir viele Informationen geliefert.\n\nAußerdem habe ich Euren König im Auge behalten. Wollt Ihr wissen, was ich erfahren habe?", sourceObjective = "Sprecht mit Furorion.", completion = "<Ein seltsamer Apparat befindet sich in einer mit Seide ausgekleideten Truhe. Es scheint, als ob man ihn als zusätzliche Verbesserung an Eurer Sha-berührten Waffe befestigen kann. Der leere Sockel ist beunruhigend – es fühlt sich an, als ob er Euch anstarren würde. Ein einzelnes, hohles, wertendes Auge...>", sourceObjectiveStatus = "unverified-source-field" }
quests[32397] = { id = 32397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es wird ihm gar nicht auffallen", description = "Ich habe beobachtet, wie Garrosh und dieser Blutelf von der Archäologischen Akademie eine Art Tagebuch mit sich herumtragen.\n\nDas Tagebuch ist immer in Reichweite. Es muss wichtig sein!\n\nWenn Ihr es schafft, für eine entsprechende Ablenkung zu sorgen, könnt Ihr das Tagebuch vielleicht vom Tisch stehlen.\n\nDiese Yaks könnten die Lösung sein: Gebt einem von ihnen einen Klaps und den Rest machen sie dann schon allein.\n\nIhr müsst nur bereit sein, schnell zu handeln!", sourceObjective = "Sorgt für eine Ablenkung im Lager und stehlt das verwitterte Tagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32411] = { id = 32411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verbleibenden Sonnenhäscher", description = "Es werden noch immer einige wichtige Vertreter der Sonnenhäscher vermisst. Es wäre gut möglich, dass man sie in Sonnenhäschers Zuflucht überrascht hat.\n\n<Rommath überreicht Euch ein offensichtlich von Blutelfenhand gefertigtes Artefakt.>\n\nDort wimmelt es nur so vor Truppen des Silberbunds. Ihr müsst Euch Zutritt verschaffen, die Träne benutzen, um diese wichtigen Persönlichkeiten zu evakuieren, und dann fliehen.\n\nBleibt am Leben, {name}.", sourceObjective = "Wendet die Träne der Sin'dorei auf Uda das Biest, den Hocharkanisten Savor, Magister Hathorel, Magister Surdiel und Magistrix Vesara an.", sourceObjectiveStatus = "unverified-source-field" }
quests[32426] = { id = 32426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerührt, nicht geschüttelt", description = "Also gut, ich werde Euch sagen, wie Ihr Connelly findet.\n\nAgent Connelly gibt sich derzeit als der Profiglücksspieler Professor Kilt aus. Er verbringt die meiste Zeit in Bizmos V.I.P.-Lounge. Man sagt, dass er wegen eines längst vergessenen Verrats hinter einem der Kämpfer her ist.\n\nLeider wird man nur auf Einladung in diesen Raum eingelassen. Doch wie es der Zufall so will, habe ich eine solche.\n\nVersucht, nicht unnötig Aufmerksamkeit zu erregen, wenn Ihr die Türsteher passiert. Falls man Euch schnappt... diese Einladung kommt nicht von mir.\n\nWas mich betrifft, haben wir uns überhaupt nie getroffen!", sourceObjective = "Findet Professor Kilt in der V.I.P.-Lounge von Bizmos Boxbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[32427] = { id = 32427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was den Anführer ausmacht", description = "Jetzt beginnt ein neuer Teil des Pandarenfeldzugs für uns. Euer Kriegshäuptling plant, die Pandaren mit der ganzen Macht des Heers der Horde zu beeindrucken. Er wird seinen Anspruch auf die Ressourcen dieses Landes erheben, sei es mit der Hilfe der Pandaren oder ohne sie.\n\nIch verstehe die Ziele Eures Anführers, aber ich möchte gern den Kriegshäuptling selbst verstehen. Was treibt ihn an? Und was will die Horde letztendlich wirklich erreichen? Ich würde mich gern mit Euch über Euren Anführer unterhalten.", sourceObjective = "Sprecht mit Furorion in der Taverne im Nebel.", completion = "Wie alle großen Anführer hat auch Garrosh sich hohe Ziele gesteckt. Doch wozu ist er letztendlich in der Lage?\n\nWichtiger noch, wozu seid IHR in der Lage? Das jüngste Blutvergießen an der Küste wird uns Gelegenheit geben, genau das herauszufinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[32428] = { id = 32428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandarischer Geisterzähmer", description = "Die Sagen erzählen von legendären Pandarengeistern, die Pandaria durchstreifen. Spürt sie auf und besiegt sie in einem Haustierkampf.", sourceObjective = "Besiegt sämtliche Pandarengeister in einem Haustierkampf.", completion = "Ich kann nicht fassen, dass Ihr diese Geister ausgeschaltet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[32429] = { id = 32429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzliches Anliegen", description = "Mein Ziel ist ein schnelles Ende dieses kostspieligen Krieges. Beweist mir, dass die Horde den Sieg verdient. Demonstriert mir Euer Können auf dem Schlachtfeld.\n\nIhr habt es hier nicht mit einer abstrakten Macht wie dem Sha zu tun: Ihr steht Eurem Feind Angesicht zu Angesicht gegenüber.\n\nWerdet Ihr triumphieren?", sourceObjective = "Tötet Allianztruppen entlang der südlichen Küsten der Krasarangwildnis bis Ihr beim Schwarzen Prinz einen respektvollen Status erreicht.", completion = "Wunderbar! Ihr habt bewiesen, dass selbst in der Hitze des Gefechts jeder Einzelne einen Unterschied machen kann. Die Allianz gerät angesichts der Macht der Horde ins Wanken, doch ihr König bleibt standhaft.\n\nIch glaube, es ist Zeit für eine anspruchsvollere Herausforderung...", sourceObjectiveStatus = "unverified-source-field" }
quests[32430] = { id = 32430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führungswechsel", description = "Es gibt da einen Zwerg der Allianz, den ich beobachtet habe. Hochmarschall Doppelzopf hat sich im Südlichen Brachland als Ärgernis erwiesen, als er sich nach dem Verlust von Bael Modan gegen die Horde zur Wehr setzte. Jetzt hat er sich in der Festung der Allianz in der Löwenlandung verschanzt und hilft dabei, die Krasaranggegenoffensive zu orchestrieren.\n\nNur eine Gruppe legendärer Helden der Horde kann ihn besiegen.\n\nWenn Ihr ihn aus dem Weg schaffen wollt, bringt Freunde mit. Jede Menge Freunde.", sourceObjective = "Tötet Hochmarschall Doppelzopf in der Löwenlandung in der Krasarangwildnis. Ihr werdet dafür eine Gruppe brauchen.", completion = "<Furorion grinst.>\n\nMan hat Euch auf die Probe gestellt, {class}. Ich wusste, dass Ihr allein in der Lage zu großen Taten seid.\n\nDoch dass Ihr Euch inmitten der tobenden Schlacht die Unterstützung einer Gruppe von Fremden sichern konntet, soll mir als Beweis für Eure herausragenden Führungsqualitäten gelten.\n\nDie Horde kann sich glücklich schätzen, Euch zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32431] = { id = 32431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm der Horde", description = "Dies ist ein weltweiter Krieg, {name}. Er ist bis nach Pandaria gelangt und hat Krisenherde in Kalimdor und den Östlichen Königreichen in Brand gesetzt. Wie verhaltet Ihr Euch in einem organisierten Kampf? Das würde ich gern selbst sehen.\n\nIch erwarte Euren Bericht von der Front.", sourceObjective = "Gewinnt Kämpfe beim Tempel von Katmogu und in der Silberbruchmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32432] = { id = 32432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seele der Horde", description = "{class}, durch Eure Augen wurde ich Zeuge der Kämpfe an der Küste und der epischen Schlachten überall auf der Welt. Ihr habt Euch als sehr geduldig... und äußerst informativ erwiesen.\n\nAuch Garrosh Höllschrei habe ich fest im Auge behalten. Würdet Ihr gerne hören, was ich dabei erfahren habe?", sourceObjective = "Sprecht mit Furorion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32434] = { id = 32434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den brennenden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32435] = { id = 32435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiter Platz", progress = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr Zweiter werden wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!" }
quests[32436] = { id = 32436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritter Platz", progress = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr den dritten und letzten Preis ergattern wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!" }
quests[32439] = { id = 32439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fließender Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den fließenden Pandarengeist in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32440] = { id = 32440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüsternder Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den flüsternden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32441] = { id = 32441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bebender Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den bebenden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32446] = { id = 32446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte auseinandernehmen", description = "Die Schredder werden dort unten zu einem Problem, {class}.\n\nWir haben die Mecha-Stampfer geschickt, aber das reicht leider nicht aus. Sie werden schneller beschädigt, als wir sie reparieren können!\n\nIch habe zufällig während einer Aufklärungsmission diese seltsame Fernbedienung gefunden. Ich glaube, wir können sie gebrauchen, wenn die Einstellungen ein wenig geändert werden.\n\nSetzt sie versuchsweise gegen die Dschungelschredder ein. Hoffentlich können sie damit zerstört werden. Wenn ja, bringt mir bitte das Altmetall mit.", sourceObjective = "Zerstört mit der rekonfigurierten Fernsteuerung die Dschungelschredder und sammelt dann 6 Stücke Metallschrott.", progress = "Wie genau funktioniert die Fernsteuerung?", completion = "Von Goblins konstruierte Geräte lassen zu Wünschen übrig, aber es muss ausreichen. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32449] = { id = 32449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Ogudei", description = "Unsere Späher am Außenposten Zündmine haben neue Aktivitäten in der Nähe eines Gebiets gemeldet, das die Ruinen von Ogudei genannt wird.\n\nWir müssen Informationen darüber sammeln, was die Allianz tut und - wichtiger noch - was sie gefunden hat. Wir können uns keine unbekannten Faktoren leisten.\n\nTrefft Euch mit Bellok Leuchtklinge im Außenposten Zündmine und findet heraus, was er weiß.", sourceObjective = "Meldet Euch bei Bellok Leuchtklinge im Außenposten Zündmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32450] = { id = 32450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt oder nie!", description = "Jetzt greifen wir sie an, {class}!\n\nMeldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine. Sie wird Euch Eure Befehle erteilen.\n\nJetzt wird sich zeigen, wie sie damit umgehen, wenn die Horde mit ganzer Macht ihre kostbare Festung stürmt!", sourceObjective = "Meldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32451] = { id = 32451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht senden", description = "Zeit, dass wir diesen Mistkerlen von der Horde die ganze Stärke der Allianz zeigen! Heute bringen wir den Kampf an ihre Tore.\n\nMeldet Euch bei Admiralin Rogers an Bord der Himmelsfeuer. Sie wird Euch weitere Anweisungen erteilen.\n\nViel Glück da draußen, {class}. Macht der Allianz Ehre!", sourceObjective = "Meldet Euch bei Himmelsadmiralin Rogers an Bord der Himmelsfeuer in der Krasarangwildnis.", completion = "Die Schlacht hat bereits begonnen, {class}. Begeben wir uns hinaus!", sourceObjectiveStatus = "unverified-source-field" }
quests[32452] = { id = 32452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und dann gab's Goblins", description = "Wir führen Krieg an allen Fronten, {class}. Sogar Pandaria selbst braucht unseren Schutz.\n\nDie Bilgewässer Goblins zerstören Land, das nicht ihnen gehört. Sie müssen aufgehalten werden!\n\nMeldet Euch bei Himmelsadmiralin Rogers auf der Himmelsfeuer. Ihr Aussichtspunkt sollte ihr einen besseren Überblick darüber verschaffen, wo die Schwachstellen sind.", sourceObjective = "Meldet Euch bei Himmelsadmiralin Rogers an Bord der Himmelsfeuer in der Krasarangwildnis.", completion = "War auch Zeit, dass wir uns um dieses Ärgernis gekümmert haben. Jemand muss diesen Bilgewässer Kümmerlingen eine Lektion erteilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32457] = { id = 32457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Donnerkönig", description = "Wisst Ihr, was sich am Kun-Lai-Gipfel ereignet hat? Die Zandalari sind in Scharen an der Nordküste gelandet und haben mit dem Erneuern alter Bündnisse begonnen. Zu diesem Zweck haben sie den Donnerkönig wiederbelebt.\n\nSelbst bei den Mogu ruft der Name des ersten Herrschers Angst und Schrecken hervor. Der Donnerkönig errichtete ein riesiges Reich der Sklaverei und des Leidens... doch auch der Macht, des Reichtums und der Pracht.\n\nWir werden ihm bald im Kampf gegenüberstehen. Kommt zu mir, wenn Eure Fraktion ihren nächsten Zug macht.", sourceObjective = "Kontaktiert Furorion im zweiten Stock der Taverne im Nebel an der Verhüllten Treppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32458] = { id = 32458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Segen des Windes...", description = "<Eine dringende Bitte kommt Euch zu Ohren.>\n\n{name}! Die Flotte meines Vaters ist nach Pandaria unterwegs. Bei gutem Wind könnte sie jeden Augenblick eintreffen.\n\nDie Pandaren haben einen Segen, der uns Glück mit dem Wetter gewähren und die Reise unserer Schiffe zu diesen Gefilden beschleunigen wird. Damit uns das Glück hold ist, müssen wir nichts weiter als Amulette des Glücks sammeln.\n\nJe näher unsere Schiffe der Insel kommen, umso weniger Amulette werden nötig sein. Doch wenn Ihr genug davon habt, können wir sie direkt hierher bringen...", sourceObjective = "Sammelt Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32459] = { id = 32459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Segen des Windes...", description = "<Eine dringende Bitte kommt Euch zu Ohren.>\n\n{name}! Die Flotte der Horde ist nach Pandaria unterwegs. Bei gutem Wind könnte sie jeden Augenblick landen.\n\nDie Pandaren haben einen Segen, der uns Glück mit dem Wetter gewähren und die Reise unserer Brüder und Schwestern zu diesen Gefilden beschleunigen wird. Damit uns das Glück hold ist, müssen wir nichts weiter als Amulette des Glücks sammeln.\n\nJe näher unsere Schiffe der Insel kommen, umso weniger Amulette werden nötig sein. Doch wenn Ihr genug davon habt, können wir sie direkt hierher bringen...", sourceObjective = "Sammelt Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32461] = { id = 32461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orden der Wolkenschlange", description = "Ahhh, Ihr seid jetzt also <stolzer Besitzer/stolze Besitzerin> einer majestätischen Wolkenschlange.\n\nEhe Ihr Euch auf dem Rücken dieser mächtigen Kreatur in die Lüfte erheben könnt, müsst Ihr die Fertigkeit sie zu reiten erwerben.\n\nDer Orden der Wolkenschlange kann Euch das gewünschte Wissen lehren.\n\nWenn Ihr unserem Weg zu folgen wünscht, sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.\n\nIch wünsche Euch Glück, {race}.", sourceObjective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[32474] = { id = 32474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapferkeitsbeweis", description = "<Ohne Vorwarnung schneidet sich Furorion in den Daumen und drückt ihn an Eure Stirn. Sein Blut brennt bei der Berührung, verschwindet jedoch schnell in Eurer Haut.>\n\nSo! Mein Auge wacht nun über Euch, {class}. Ich beobachte Euch.\n\nDie Pandaren wissen das Konzept der \"Tapferkeit\" genauso zu schätzen wie die Allianz. Auf diesem Kontinent gibt es viele Möglichkeiten, Euch würdig zu erweisen - von alltäglichen Aufgaben bis hin zum Bezwingen heroischer Gegner in ihrem Versteck. Ich überlasse es Euch, Euren eigenen Weg zu wählen.\n\nBeweist mir Euren Mut, {name}!", sourceObjective = "Erlangt den Erfolg \"Tapferkeitsbeweis\", indem Ihr insgesamt 1600 Tapferkeitspunkte verdient.", completion = "<Furorion nickt langsam.>\n\nJa. {name}. Ich habe Eure Taten verfolgt und war höchst beeindruckt.\n\nIhr seid wahrlich ein Bote der Änderung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32476] = { id = 32476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapferkeitsbeweis", description = "<Ohne Vorwarnung schneidet sich Furorion in den Daumen und drückt ihn an Eure Stirn. Sein Blut brennt bei der Berührung, verschwindet jedoch schnell in Eurer Haut.>\n\nSo! Mein Auge wacht nun über Euch, {class}. Ich beobachte Euch.\n\nDie Pandaren wissen das Konzept der \"Tapferkeit\" genauso zu schätzen wie die Horde. Auf diesem Kontinent gibt es viele Möglichkeiten, Euch würdig zu erweisen - von alltäglichen Aufgaben bis hin zum Bezwingen heroischer Gegner in ihrem Versteck. Ich überlasse es Euch, Euren eigenen Weg zu wählen.\n\nBeweist mir Euren Mut, {name}!", sourceObjective = "Erlangt den Erfolg \"Tapferkeitsbeweis\", indem Ihr insgesamt 1600 Tapferkeitspunkte verdient.", completion = "<Furorion nickt langsam.>\n\nJa. {name}. Ich habe Eure Taten verfolgt und war höchst beeindruckt.\n\nIhr seid wahrlich ein Bote der Änderung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32496] = { id = 32496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!" }
quests[32497] = { id = 32497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in der Schreckensöde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32498] = { id = 32498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
